      (v_set_id, 1, E'सबैभन्दा सानो देश भ्याटिकन सिटभन्दा नेपाल करिब कति ठूलो रहेको छ?', E'३,२४,५०० गुणा', E'३,३३,५०० गुणा', E'३,३२,५०० गुणा', E'३,२१,५०० गुणा', 'A', E'**नेपाल सबैभन्दा सानो देश भ्याटिकन सिटि भन्दा करिब ३,२४,५०२.२७ गुणा ठूलो रहेको छ।**\n- सबैभन्दा ठूलो देश रुसभन्दा नेपाल ११६.१७ गुणा सानो छ।', 'nepali'),
      (v_set_id, 2, E'नेपालको उत्तर दक्षिण औसत चौडाई कति रहेको छ?', E'१९३ कि.मी.', E'२४१ कि.मी.', E'१४५ कि.मी.', E'८८५ कि.मी.', 'A', E'नेपालको उत्तर दक्षिण औसत चौडाई **१९३ कि.मी.** रहेको छ। यसको अधिकतम चौडाई २४१ कि.मी. र न्यूनतम चौडाई १४५ कि.मी. छ।\nनोट: नेपालको पूर्व-पश्चिम औसत लम्बाई ८८५ कि.मी. रहेको छ।', 'nepali'),
      (v_set_id, 3, E'नेपालको भूगोल अन्तर्गत नेपालको दक्षिणी विन्दुमा रहेको ठाउँ कुन विकल्प सहि छ?', E'झापाको धुलाबारी', E'झापाको लोदाबारी', E'झापाको गोदावरी', E'झापाको उर्लाबारी', 'B', E'नेपालको दक्षिणी विन्दु **झापाको लोदाबारी** हो।\nनेपालका चार सिमानाका विन्दुहरू यसप्रकार छन्:\n- पूर्वी: ताप्लेजुङको लेलेप\n- पश्चिमी: कन्चनपुरको दोधारा\n- उत्तरी: हुम्लाको च्याङ्ला\n- दक्षिणी: झापाको लोदाबारी', 'nepali'),
      (v_set_id, 4, E'नेपालको क्षेत्रफलका सम्बन्धमा तल केहि जोडाहुहरु दिइएको छ। उक्त जोडाको अध्ययन गरी गलत जोडाहुहरु कुन-कुन हुन? पत्ता लगाउनुहोस्।', E'२ मात्र गलत', E'३ मात्र गलत', E'२,३,४ गलत', E'२, ३ मात्र गलत', 'D', E'**नेपालको क्षेत्रफल वर्गमाइलमा ५६,८२७ र चीन भन्दा करिब ६५.२ गुणा सानो रहेको छ।**\n- नेपालको क्षेत्रफल १,४७,१८१ वर्ग कि.मि. हो।\n- नेपाल भारत भन्दा करिब २२.३३ गुणा सानो छ।', 'nepali'),
      (v_set_id, 5, E'नेपालको प्रमाणिक समय सन्दर्भमा गौरीशंकर हिमाललाई काटेर गएको कति ° देशान्तरलाई आधार मानिएको छ?', E'86° 15''', E'85° 15''', E'85° 25''', E'86° 25''', 'A', E'नेपालको प्रमाणिक समय गौरीशंकर हिमाललाई काटेर गएको **८६° १५''** पूर्वी देशान्तरलाई आधार मानिएको छ। यो समय वि.सं. २०४२ साल वैशाख १ गतेबाट लागू भएको हो।\nनोट: गौरीशंकर हिमालको उचाइ ७,१३४ मिटर रहेको छ र यो दोलखा जिल्लामा पर्दछ।', 'nepali'),
      (v_set_id, 6, E'नेपालको प्रमाणिक समय कुन हो ?', E'UTC +6:00', E'UTC +5:45', E'UTC +5:30', E'UTC +4:45', 'B', E'नेपालको प्रमाणिक समय **UTC +5:45** हो।\n- नेपालको समय ग्रीनवीचको समयभन्दा ५ घण्टा ४५ मिनेट चलाख रहेको छ।\nनोट: यो समय वि.सं. २०४२ साल वैशाख १ गतेबाट लागू भएको हो र गौरीशंकर हिमाललाई आधार मानेर निर्धारण गरिएको छ।', 'nepali'),
      (v_set_id, 7, E'अक्षांशका हिसाबले नेपाल कुन गोलाद्र्धमा रहेको छ?', E'पूर्वी गोलाद्र्धमा', E'पश्चिमी गोलाद्र्धमा', E'उत्तरी गोलाद्र्धमा', E'दक्षिणी गोलाद्र्धमा', 'C', E'**अक्षांशका हिसाबले नेपाल उत्तरी गोलाद्र्धमा अवस्थित छ।**\n- नेपाल २६ डिग्री २२ मिनेट उत्तरी अक्षांशदेखि ३० डिग्री २७ मिनेट उत्तरी अक्षांशसम्म फैलिएको छ।', 'nepali'),
      (v_set_id, 8, E'नेपाललाई भारतका कतिवटा प्रान्तले छोएको छ?', E'६ वटा', E'५ वटा', E'७ वटा', E'८ वटा', 'B', E'**नेपाललाई भारतका पाँचवटा प्रान्तले छोएको छ।**\n- यी प्रान्तहरू पूर्वबाट क्रमशः सिक्किम, पश्चिम बङ्गाल (दार्जिलिङ), बिहार, उत्तर प्रदेश र उत्तराखण्ड हुन्।\nनोट: बिहारले सबैभन्दा बढी र सिक्किमले सबैभन्दा कम सिमाना छोएको छ।', 'nepali'),
      (v_set_id, 9, E'नेपाल र भारतको विवादित क्षेत्र लिम्पियाधुराको क्षेत्रफल कति रहेको छ?', E'३२४ वर्ग कि. मी.', E'३३५ वर्ग कि. मी.', E'३४५ वर्ग कि. मी.', E'३९५ वर्ग कि. मी.', 'B', E'नेपाल र भारतबीच विवादित क्षेत्र लिम्पियाधुराको क्षेत्रफल **३३५ वर्ग कि. मी.** रहेको छ।\nनोट: दार्चुला जिल्लाका लिम्पियाधुरा, कालापानी र लिपुलेक इलाकामा रहेका गुन्जी, नाभी, कुटी लगायतका केही भूभाग नेपालको क्षेत्रफलमा समावेश नभएको मानिन्छ। यी इलाका थप गर्दा नेपालको कुल क्षेत्रफल करिब १,४७,५१६ वर्ग कि.मि. पुग्ने अनुमान गरिएको छ।', 'nepali'),
      (v_set_id, 10, E'नेपालको सबैभन्दा नजिकमा रहेको सार्क राष्ट्र राजधानी कुन देशको हो ?', E'अफगानिस्तान', E'भारत', E'बंगलादेश', E'भुटान', 'D', E'नेपालको सबैभन्दा नजिकमा रहेको सार्क राष्ट्रको राजधानी **भुटानको थिम्पु** हो।\n- भारत नेपालको छिमेकी राष्ट्र भए तापनि यसको राजधानी नयाँ दिल्ली थिम्पुभन्दा टाढा पर्दछ।\n- बंगलादेश नेपालबाट करिब २७ कि.मि. को दूरीमा रहेको नजिकको देश हो, तर यसको राजधानी ढाका थिम्पुभन्दा टाढा छ।\n- अफगानिस्तानको राजधानी काबुल अन्य विकल्पहरूभन्दा टाढा रहेको छ।\nनोट: नेपालबाट भुटानको राजधानी थिम्पुको हवाई दूरी करिब ४०० कि.मि. छ।', 'nepali'),
      (v_set_id, 11, E'नेपालको कुल अन्तर्राष्ट्रिय सिमाना कति कि.मि. रहेको छ?', E'२८२६ कि.मि.', E'२८९६ कि.मि.', E'२९३६ कि.मि.', E'२९२६ कि.मि.', 'D', E'नेपालको कुल अन्तर्राष्ट्रिय सिमाना **२९२६ कि.मि.** रहेको छ। यो भारत र चीन दुई देशसँग जोडिएको छ।\nनोट: नेपालको सिमाना भारतसँग १६९० कि.मि. र चीनसँग १२३६ कि.मि. रहेको छ (१६९० + १२३६ = २९२६)।', 'nepali'),
      (v_set_id, 12, E'नेपाल समुन्द्र सतहदेखि कति कि.मि. टाढा रहेको छ?', E'१२२७ कि.मि.', E'१११७ कि.मि.', E'११२७ कि.मि.', E'१२१७ कि.मि.', 'C', E'नेपाल समुन्द्र सतहदेखि करीब **११२७ कि.मि.** टाढा रहेको छ। नेपालको सबैभन्दा नजिकको समुन्द्र बंगालको खाडी (हिन्द महासागर) हो।', 'nepali'),
      (v_set_id, 13, E'नेपाल एसियाको कति औं ठूलो देश हो?', E'२४ औं', E'२५ औं', E'२६ औं', E'२७ औं', 'C', E'क्षेत्रफलको आधारमा नेपाल एसियाको **२६ औं** ठूलो देश हो।\nनोट: नेपाल विश्वको ९३ औं ठूलो, सार्कमा ५ औं ठूलो र विश्वको २१ औं ठूलो भूपरिवेष्ठित देश हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

