  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'पहाडबाट पाँच वटा जिल्ला हिमाली क्षेत्रमा स्तरन्नोति पछिको पहाडको नयाँ क्षेत्रफल प्रतिशत कति हुन आउँछ ?', E'२२.५ प्रतिशत', E'२६.५ प्रतिशत', E'२७.२ प्रतिशत', E'२८.५ प्रतिशत', 'C', E'पाँच वटा जिल्लालाई पहाडबाट हिमाली क्षेत्रमा स्तरन्नोति गरेपछि पहाडी क्षेत्रको नयाँ क्षेत्रफल **२७.२ प्रतिशत** हुन आउँछ।\nनोट: यस परिवर्तनपछि हिमाली क्षेत्रको क्षेत्रफल २४.२ प्रतिशत र तराई क्षेत्रको क्षेत्रफल १७ प्रतिशत रहेको छ।', 'nepali'),
      (v_set_id, 2, E'महाभारत पहाडको दोस्रो अग्लो टाकुरा कुन हो?', E'फुलचोकी', E'गाभा', E'शैलुङ', E'द्यामके', 'D', E'**महाभारत पहाडको दोस्रो अग्लो टाकुरा द्यामके हो।**\n- महाभारत पर्वतको सबैभन्दा अग्लो टाकुरा शैलुङ हो।\n- द्यामके खोटाङ र भोजपुर जिल्लाको सिमानामा पर्दछ।', 'nepali'),
      (v_set_id, 3, E'नेपालको भूगोलमा ल्याचुङ भञ्ज्याङ कुन जिल्लामा रहेको छ?', E'बझाङ', E'संखुवासभा', E'गोर्खा', E'डोल्पा', 'C', E'**ल्याचुङ भञ्ज्याङ गोर्खा जिल्लामा अवस्थित छ।**\n- गोर्खा जिल्लामा थाप्ले भञ्ज्याङ, लार्के भञ्ज्याङ, ग्याला भञ्ज्याङ, मेलाट साचिङ भञ्ज्याङ र याण्डोन भञ्ज्याङ पनि रहेका छन्।\n- बझाङ जिल्लामा साइपाल हिमाल र सुर्मा सरोवर जस्ता महत्वपूर्ण भौगोलिक स्थलहरू छन्।\n- संखुवासभा जिल्लामा मकालु हिमाल र अरुण नदीको उद्गमस्थल पर्दछ।\n- डोल्पा जिल्ला नेपालको सबैभन्दा ठूलो जिल्ला हो र यहाँ शे-फोक्सुण्डो ताल अवस्थित छ।', 'nepali'),
      (v_set_id, 4, E'हुम्ला, जुम्ला, मुगु, डोल्पा, मुस्ताङ र मनाङ लगायतका हिमाली उपत्यका देहायका मध्ये कुन हिमाली क्षेत्रमा रहेको छ?', E'मुख्य हिमाली क्षेत्र', E'भित्री हिमाली क्षेत्र', E'सीमान्त हिमाली क्षेत्र', E'हिमाल हिमाली क्षेत्र', 'B', E'हुम्ला, जुम्ला, मुगु, डोल्पा, मुस्ताङ र मनाङ लगायतका हिमाली उपत्यकाहरू **भित्री हिमाली क्षेत्रमा** पर्दछन्। यो क्षेत्र मुख्य हिमालयबाट उत्तर र तिब्बतको तटवर्ती क्षेत्रबाट दक्षिणतिर अवस्थित छ।', 'nepali'),
      (v_set_id, 5, E'भित्रि मधेशको अवस्थिति देहाएका मध्ये कुन विकल्प सहि छ?', E'चुरे र भावर विचमा', E'चुरे र महाभारत विचमा', E'महाभारत र भावर विचमा', E'महाभारत र मध्यभूमी विचमा', 'B', E'भित्री मधेश **चुरे र महाभारत पर्वत श्रेणीको बीचमा** अवस्थित छ। समुन्द्र सतहदेखि ६१० मिटरको उचाइसम्म चारैतिर पहाड पर्वतले घेरिएर फैलिएका विशाल फाँटलाई भित्री मधेश वा दून क्षेत्र भनिन्छ।\nनोट: यो क्षेत्रले मुलुकको कुल क्षेत्रफलको ८.५ प्रतिशत भू-भाग समेटेको छ।', 'nepali'),
      (v_set_id, 6, E'सीमान्त हिमाली क्षेत्र कति मिटर उचाई सम्म फैलिएको छ?', E'५००० मि.', E'६००० मि.', E'७००० मि.', E'८००० मि.', 'C', E'सीमान्त हिमाली क्षेत्र (Tibetan Plateau) ६,००० मिटर देखि **७,००० मिटर** उचाई सम्म फैलिएको छ।\nनोट: नेपालको हिमाली प्रदेशलाई मुख्य हिमाली क्षेत्र (५,००० - ८,८४८.८६ मि.), भित्री हिमाली क्षेत्र (२,४०० - ५,००० मि.) र सीमान्त हिमाली क्षेत्र गरी तीन भागमा विभाजन गरिएको छ।', 'nepali'),
      (v_set_id, 7, E'चुरे पर्वतको सबैभन्दा फराकिलो स्थान देहाएका मध्ये कुन जिल्लामा रहेको छ?', E'दाङ', E'कैलाली', E'मकवानपुर', E'दोलखा', 'A', E'चुरे पर्वतको सबैभन्दा फराकिलो स्थान **दाङ जिल्लाको देउखुरी उपत्यका**मा रहेको छ, जुन १२ माइल चौडा छ।\n- कैलाली जिल्लामा चुरे पर्वतको सबैभन्दा धेरै भू-भाग (क्षेत्रफल) पर्दछ।', 'nepali'),
      (v_set_id, 8, E'हिमालयको बिचमा रहेको तराईको क्षेत्रलाई के भनिन्छ?', E'हिमांचल क्षेत्र', E'चुरे क्षेत्र', E'दुन क्षेत्र', E'महाभारत क्षेत्र', 'C', E'मध्य हिमालय र शिवालिक हिमालयको बीचमा पाइने उपत्यकाहरूलाई **दुन क्षेत्र** (भित्री मधेस) भनिन्छ।\n- चुरे क्षेत्र (शिवालिक) नेपालको सबैभन्दा दक्षिणमा रहेको र सबैभन्दा नयाँ पर्वत श्रृंखला हो।\n- महाभारत क्षेत्र चुरे श्रृंखलाको उत्तर र मुख्य हिमालयको दक्षिणमा अवस्थित छ।\n- हिमांचल क्षेत्र नेपालको भौगोलिक विभाजनको औपचारिक शब्दावली होइन, तर सामान्यतया हिमाली प्रदेशलाई जनाउन प्रयोग हुन सक्छ।', 'nepali'),
      (v_set_id, 9, E'नेपालको सबैभन्दा कान्छो उपत्यकाका रूपमा प्रसिद्ध ''जोगबुडा उपत्यका'' कुन जिल्लामा अवस्थित प्रसिद्ध उपत्यका हो?', E'रुकुम पश्चिम', E'लमजुङ', E'डडेलधुरा', E'मुस्ताङ', 'C', E'**नेपालको सबैभन्दा कान्छो उपत्यका मानिने जोगबुडा उपत्यका डडेलधुरा जिल्लामा अवस्थित छ।**\n- रुकुम पश्चिम जिल्लामा चौरजहारी उपत्यका पर्दछ।\n- लमजुङ जिल्लामा कर्पूटार उपत्यका रहेको छ।\n- मुस्ताङ जिल्लामा थाकखोला उपत्यका अवस्थित छ।', 'nepali'),
      (v_set_id, 10, E'''पाटन उपत्यका'' कुन जिल्लामा अवस्थित रहेको छ?', E'प्युठान', E'बैतडी', E'चितवन', E'ललितपुर', 'B', E'**''पाटन उपत्यका'' बैतडी जिल्लामा अवस्थित छ।**\n- प्युठान जिल्लामा भिमरूक उपत्यका रहेको छ।\n- चितवन जिल्लामा माडी उपत्यका अवस्थित छ।\n- ललितपुर जिल्ला काठमाडौं उपत्यकाको एक भाग हो, तर प्रश्नमा सोधिएको पाटन उपत्यका बैतडीमा पर्दछ।\nनोट: दार्चुला जिल्लामा व्यास उपत्यका रहेको छ।', 'nepali'),
      (v_set_id, 11, E'काठमाडौं उपत्यकाको क्षेत्रफल कति रहेको छ?', E'६४२ वर्ग कि.मि.', E'६६६ वर्ग कि.मि.', E'५४२ वर्ग कि.मि.', E'३४२ वर्ग कि.मि.', 'A', E'काठमाडौं उपत्यकाको क्षेत्रफल **६४२ वर्ग कि.मि.** रहेको छ।\n- सुर्खेत उपत्यकाको क्षेत्रफल ४१ वर्ग कि.मि. छ।\n- पोखरा उपत्यकाको क्षेत्रफल १२४ वर्ग कि.मि. छ।\n- दाङ उपत्यकाको क्षेत्रफल १००० वर्ग कि.मि. रहेको छ।', 'nepali'),
      (v_set_id, 12, E'विश्वको सबैभन्दा गहिरो उपत्यका कुन हो?', E'ताराकोट', E'नुब्री', E'अरुण', E'सिञ्जा', 'C', E'**विश्वको सबैभन्दा गहिरो उपत्यका अरुण उपत्यका हो, जुन संखुवासभा जिल्लामा पर्दछ।**\n- ताराकोट उपत्यका डोल्पा जिल्लामा पर्दछ।\n- नुब्री उपत्यका गोरखा जिल्लामा पर्दछ।\n- सिञ्जा उपत्यका जुम्ला जिल्लामा पर्दछ।', 'nepali'),
      (v_set_id, 13, E'भौगोलिक विभाजन अन्तर्गत पहाडी प्रदेशको अवस्थिति देहायका मध्ये कुन विकल्प सहि छ पहिचान गर्नुहोस् ?', E'५०० देखि ३००० मि.', E'५०० देखि ३५०० मि.', E'६०० देखि ३५०० मि.', E'६०० देखि ३००० मि.', 'D', E'भौगोलिक विभाजन अनुसार पहाडी प्रदेश **६०० देखि ३००० मिटर**को उचाइमा अवस्थित छ।\n- हिमाली प्रदेश ३००० देखि ८८४८.८६ मिटर र तराई प्रदेश ५९ देखि ६०० मिटरको उचाइमा पर्दछन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — भू-आकृति', 13;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- हिमाल (15 questions)  →  subtopic slug: nepal-geography-himalayan-ranges
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-himalayan-ranges' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-himalayan-ranges';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — हिमाल' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — हिमाल';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — हिमाल', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'मकालु हिमाल कुन जिल्लामा रहेको छ?', E'सोलुखुम्बु', E'सङ्खुवासभा', E'ताप्लेजुङ', E'गोरखा', 'B', E'**मकालु हिमाल सङ्खुवासभा जिल्लामा रहेको छ।**\n- सोलुखुम्बु जिल्लामा सगरमाथा, ल्होत्से र चो ओयु हिमाल रहेका छन्।\n- ताप्लेजुङ जिल्लामा कञ्चनजङ्घा हिमाल रहेको छ।\n- गोरखा जिल्लामा मनास्लु हिमाल रहेको छ।\nनोट: धवलागिरि म्याग्दी/मुस्ताङ र अन्नपूर्ण कास्की जिल्लामा रहेका छन्।', 'nepali'),
      (v_set_id, 2, E'आठ हजार मिटर भन्दा अग्ला आठवटा हिमाल मध्ये गण्डकी प्रदेशमा अवस्थित हिमालको संख्या कति रहेको छ?', E'५ वटा', E'४ वटा', E'३ वटा', E'२ वटा', 'C', E'नेपालमा रहेका आठ हजार मिटर भन्दा अग्ला आठवटा हिमालमध्ये गण्डकी प्रदेशमा **३ वटा** हिमाल अवस्थित छन्।\n- गण्डकी प्रदेशमा धवलागिरी, मनास्लु र अन्नपूर्ण हिमाल रहेका छन्।\n- बाँकी पाँचवटा हिमाल (सगरमाथा, कञ्चनजङ्घा, ल्होत्से, मकालु, चोओयु) कोशी प्रदेशमा रहेका छन्।', 'nepali'),
      (v_set_id, 3, E'विश्वको सर्वोच्च शिखर सगरमाथा नेपालका ८ हजार मिटर भन्दा अग्ला हिमाल मध्ये पश्चिमबाट कति औं स्थानमा पर्दछ?', E'चौथो', E'पाँचौ', E'तेस्रो', E'छैठौं', 'B', E'नेपालमा रहेका ८,००० मिटरभन्दा अग्ला हिमालहरूलाई पश्चिमबाट पूर्वतर्फ गणना गर्दा सगरमाथा **पाँचौँ स्थानमा** पर्दछ।\nनोट: पूर्वबाट गणना गर्दा भने सगरमाथा चौथो स्थानमा आउँछ।', 'nepali'),
      (v_set_id, 4, E'नेपालको आठ हजार मिटर भन्दा अग्ला ८ वटा हिमाल मध्ये सबैभन्दा पश्चिममा रहेको हिमाल कुन हो ?', E'अन्नपूर्ण', E'धौलागिरी', E'मनास्लु', E'कन्चनजंघा', 'B', E'**नेपालको आठ हजार मिटर भन्दा अग्ला हिमालहरू मध्ये सबैभन्दा पश्चिममा धौलागिरी हिमाल रहेको छ।**\n- पूर्वबाट पश्चिमको क्रममा कन्चनजंघा, मकालु, ल्होत्से, सगरमाथा, चोयु, मनास्लु, अन्नपूर्ण र धौलागिरी पर्दछन्।', 'nepali'),
      (v_set_id, 5, E'माछापुच्छ्रे हिमालको उचाइ कति रहेको छ ?', E'६९९३ मिटर', E'६९९७ मिटर', E'७०५९ मिटर', E'७०३५ मिटर', 'A', E'माछापुच्छ्रे हिमालको उचाइ **६९९३ मिटर** रहेको छ। यो अन्नपूर्ण हिमशृंखला अन्तर्गत कास्की जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 6, E'गुरुँस हिमश्रृंखला अन्तर्गत कुन हिमाल पर्छ ?', E'गणेश', E'चामर', E'अपि', E'तिलिचो', 'C', E'**अपि हिमाल गुरुँस हिमश्रृंखला अन्तर्गत पर्दछ।**\n- गणेश हिमाल लाङटाङ हिमश्रृंखलामा पर्दछ।\n- चामर हिमाल धौलागिरी हिमश्रृंखलामा पर्दछ।\n- तिलिचो हिमाल अन्नपूर्ण हिमश्रृंखलामा पर्दछ।\nनोट: अपि हिमाल दार्चुला जिल्लाको सबैभन्दा अग्लो भाग हो र यसको उचाई ७,१३२ मिटर (२३,३९९ फिट) रहेको छ।', 'nepali'),
      (v_set_id, 7, E'नेपालको अन्नपूर्ण हिमाल विश्वको कति औं अग्लो शिखर हो?', E'नवौं', E'आठौं', E'दशौं', E'एघारौं', 'C', E'अन्नपूर्ण हिमाल विश्वको **दशौं** अग्लो शिखर हो, जसको उचाइ ८,०९१ मिटर छ। यो हिमाल नेपालको भने आठौं अग्लो शिखर हो।\nनोट: विश्वको नवौं अग्लो शिखर पाकिस्तानमा अवस्थित नंगा पर्वत हो।', 'nepali'),
      (v_set_id, 8, E'दोलखामा अवस्थित नेपालको चर्चित हिमाल गौरिशंकर हिमालको उचाइ कति रहेको छ?', E'७१३४ मिटर', E'७१३१ मिटर', E'७१३७ मिटर', E'७२३३ मिटर', 'A', E'दोलखा जिल्लामा अवस्थित गौरिशंकर हिमालको उचाइ **७,१३४ मिटर** रहेको छ। यही हिमाललाई काटेर गएको ८६ डिग्री १५ मिनेट पूर्वी देशान्तरलाई आधार मानेर नेपालको प्रमाणिक समय निर्धारण गरिएको हो।\nनोट: नेपालको प्रमाणिक समय वि.सं. २०४२ साल वैशाख १ गतेबाट लागू भएको हो र यो ग्रीनवीचको समयभन्दा ५ घण्टा ४५ मिनेट छिटो छ।', 'nepali'),
      (v_set_id, 9, E'देहायका मध्ये सबैभन्दा अग्लो हिमाल कुन हो? पहिचान गर्नुहोस्', E'चोयु', E'मनास्लु', E'मकालु', E'धवलागिरि', 'C', E'दिएका विकल्पहरूमध्ये **मकालु हिमाल (८,४६३ मिटर)** सबैभन्दा अग्लो हो।\n- चोयु हिमालको उचाइ ८,२०१ मिटर रहेको छ।\n- धवलागिरि हिमालको उचाइ ८,१६७ मिटर रहेको छ।\n- मनास्लु हिमालको उचाइ ८,१६३ मिटर रहेको छ।', 'nepali'),
      (v_set_id, 10, E'सोलुखुम्बु जिल्लामा पर्ने ८००० मि भन्दा पछिको अग्लो हिमाल नुप्से हिमालको उचाइ कति रहेको छ?', E'७,२९६ मिटर', E'७,५९९ मिटर', E'७,९६३ मिटर', E'७,८५५ मिटर', 'D', E'सोलुखुम्बु जिल्लामा पर्ने नुप्से हिमालको उचाइ **७,८५५ मिटर** रहेको छ।\n- ७,५९९ मिटर शान्ति पिकको उचाइ हो भने ७,१६३ मिटर गणेश हिमालको उचाइ हो।', 'nepali'),
      (v_set_id, 11, E'सगरमाथालाई माउन्ट एभरेष्ट भनि नामाकरण कहिले गरियो?', E'सन् १८५५', E'सन् १८६५', E'सन् १८७५', E'सन् १८८५', 'B', E'सगरमाथालाई **सन् १८६५** मा ''माउन्ट एभरेष्ट'' भनी नामाकरण गरिएको थियो।\nनोट: यो नामकरण तत्कालीन ब्रिटिस सर्भेयर जनरल सर जर्ज एभरेष्टको सम्मानमा गरिएको थियो।', 'nepali'),
      (v_set_id, 12, E'६ चुलीको हिमालको उपनामले नेपालको कुन हिमाललाई चिनिन्छ?', E'कन्चनजंघा', E'सगरमाथा', E'धौलागिरी', E'मकालु', 'C', E'**धौलागिरी हिमाल**लाई ६ चुलीको हिमाल र सेतो हिमालको उपनामले चिनिन्छ।\n- कन्चनजंघा हिमाललाई पाँचौं चुली र नेपाल पिक भनिन्छ।\n- सगरमाथालाई पन्ध्रौं चुली, संसारको आमा, र तेस्रो ध्रुव जस्ता उपनामले चिनिन्छ।\n- मकालु हिमाललाई जन्जु हिमाल र उच्च कालो हिमाल पनि भनिन्छ।', 'nepali'),
      (v_set_id, 13, E'मकालु हिमाल कुन हिमशृंखला अन्तर्गत रहेको छ ?', E'महालंगुर', E'गणेश', E'खुम्बु', E'कुम्भकर्ण', 'D', E'मकालु हिमाल **कुम्भकर्ण** हिमशृंखला अन्तर्गत रहेको छ।\n- महालंगुर/खुम्बु हिमशृंखलामा सगरमाथा, ल्होत्से र चो ओयु हिमालहरू पर्दछन्।\n- गणेश हिमशृंखला (मानसिरी) मा मनास्लु हिमाल पर्दछ।\nनोट: ८,००० मिटरभन्दा अग्ला हिमालहरूमध्ये कञ्चनजङ्घा, धवलागिरि र अन्नपूर्ण हिमालहरू आफ्नै नामको हिमशृंखलामा पर्दछन्।', 'nepali'),
      (v_set_id, 14, E'देहायका मध्ये कुन नेपाली हिमालको हिमशृङ्खला अन्नपूर्ण हो?', E'मनास्लु', E'माछापुच्छ्रे', E'धौलागिरी', E'गौरिशंकर', 'B', E'**माछापुच्छ्रे हिमाल अन्नपूर्ण हिमशृङ्खलामा पर्दछ।**\n- मनास्लु हिमाल गणेश हिमशृङ्खलामा पर्दछ।\n- धौलागिरी हिमाल धौलागिरी हिमशृङ्खलामा पर्दछ।\n- गौरिशंकर हिमाल रोल्वालिङ हिमशृङ्खलामा पर्दछ।', 'nepali'),
      (v_set_id, 15, E'कुमारी हिमालको उपनामले कुन हिमाललाई चिनिन्छ?', E'जुगल', E'अन्नपूर्ण', E'माछापुच्छ्रे', E'मनास्लु', 'C', E'**माछापुच्छ्रे हिमाललाई कुमारी हिमाल वा ''Mother Horn of Nepal'' को उपनामले चिनिन्छ।**\n- जुगल हिमाललाई भर्जिन हिमाल भनिन्छ।\n- अन्नपूर्ण हिमाललाई देवता हिमाल भनिन्छ।\n- मनास्लु हिमाललाई किलर माउन्टेन वा कटनको उपनामले चिनिन्छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — हिमाल', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- नदी (19 questions)  →  subtopic slug: nepal-geography-rivers
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-rivers' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-rivers';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — नदी' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — नदी';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — नदी', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'ठूलो भेरी र सानो भेरीको दोभान जाजरकोटको कुन ठाउँमा रहेको छ?', E'रिम्ना', E'दल्लि', E'मटेला', E'खलंगा', 'B', E'**ठूलो भेरी र सानो भेरीको दोभान जाजरकोटको दल्लिमा रहेको छ।**\n- रिम्ना जाजरकोट र रुकुम पश्चिमको सिमानामा पर्ने एक स्थान हो।\n- मटेला जाजरकोट जिल्लाको एक गाउँपालिका हो।\n- खलंगा जाजरकोट जिल्लाको सदरमुकाम हो।\nनोट: भेरी नदी कर्णाली नदीको सहायक नदी हो।', 'nepali'),
      (v_set_id, 2, E'नेपालको सबैभन्दा लामो नदि कर्णालीको लम्बाई कति रहेको छ?', E'७०५ कि.मी.', E'५१५ कि.मी.', E'७२० कि.मी.', E'१०८० कि.मी.', 'A', E'नेपालको सबैभन्दा लामो नदी कर्णालीको लम्बाई **७०५ कि.मी.** रहेको छ।\n- कोशी नदीको कूल लम्बाई ७२० कि.मी. छ भने नेपालभित्र मात्र यसको लम्बाई २०० कि.मी. छ।\n- गण्डकी नदीको कूल लम्बाई ३३८ कि.मी. छ।', 'nepali'),
      (v_set_id, 3, E'नेपालको कुल क्षेत्रफलको कति भू-भाग नदीनालाले ओगटेको छ?', E'३.९ प्रतिशत', E'३.०९ प्रतिशत', E'७.०६ प्रतिशत', E'७.६ प्रतिशत', 'A', E'**नेपालको कुल क्षेत्रफलको ३.९ प्रतिशत भू-भाग नदीनालाले ओगटेको छ।**\n- नेपालको स्थलक्षेत्र १२.९४% छ भने जलक्षेत्र ७.०६% रहेको छ।', 'nepali'),
      (v_set_id, 4, E'महाकाली नदीको उद्गम स्थल कुन हिमाल हो ?', E'अपि हिमाल', E'सैपाल हिमाल', E'धौलागिरी हिमाल', E'मुकुट हिमाल', 'A', E'महाकाली नदीको उद्गम स्थल **अपि हिमाल** हो।\n- सैपाल हिमालबाट सेती नदीको उद्गम हुन्छ।\n- धौलागिरी हिमाल सानो भेरी नदीको उद्गम स्थल हो।\n- मुकुट हिमाल ठूलो भेरी नदीको उद्गम स्थल हो।', 'nepali'),
      (v_set_id, 5, E'इन्द्रावती नदी र सुनकोसी नदीको दोभान स्थल कुन विकल्प सहि छ?', E'तुम्लिङटार', E'बराहक्षेत्र', E'बेनिघाट', E'दोलालघाट', 'D', E'**इन्द्रावती नदी र सुनकोसी नदीको दोभान स्थल दोलालघाट हो।**\n- तुम्लिङटार अरुण नदी र सभाखोलाको दोभान स्थल हो।\n- बराहक्षेत्र कोका नदी र कोशी नदीको दोभान स्थल हो।\nनोट: दोलालघाट काभ्रे जिल्लामा पर्दछ।', 'nepali'),
      (v_set_id, 6, E'कन्काई नदीलाई भारतमा बेरङ भनिन्छ भने महाकालीलाई के भनिन्छ ?', E'घोघरा', E'सरयु', E'महानन्दा', E'शारदा', 'D', E'**महाकाली नदीलाई भारतमा शारदा नामले चिनिन्छ।**\n- मेची नदीलाई भारतमा महानन्दा भनिन्छ।\n- बबई नदीलाई भारतमा सरयु भनिन्छ।\n- घोघरा भारतमा कर्णाली नदीको नाम हो।', 'nepali'),
      (v_set_id, 7, E'जोडा मिलाउनुहोस्: नदी: (a) तमोर, (b) दुधकोशी, (c) लिखु, (d) इन्द्रावती उदगमस्थल: 1. रोल्वालिङ, 2. जुगल, 3. कुम्भकर्ण हिमाल, 4. दुधकुण्ड', E'a3, b2, c1, d4', E'a3, b1, c2, d4', E'a2, b3, c4, d1', E'a3, b4, c1, d2', 'D', E'नेपालका प्रमुख नदीहरूको उद्गमस्थल यसप्रकार रहेको छ: **तमोर नदीको कुम्भकर्ण हिमाल, दुधकोशीको दुधकुण्ड, लिखुको रोल्वालिङ र इन्द्रावतीको जुगल हिमाल।**', 'nepali'),
      (v_set_id, 8, E'जोडा मिलाउनुहोस्।', E'a3, b2, c1, d4', E'a3, b1, c2, d4', E'a2, b3, c4, d1', E'a3, b4, c1, d2', 'D', E'**नेपालका नदीहरू र तिनका उद्गमस्थलको सही जोडा यस प्रकार छ: दरौंदीको उद्गमस्थल बुद्ध हिमाल, बुढी गण्डकीको गणेश हिमाल, मर्स्याङ्दीको दामोदर हिमाल र बुढी गंगाको जगदुल्ला ताल हो।**\n- दरौंदी नदी बुद्ध हिमालबाट उत्पत्ति हुन्छ।\n- बुढी गण्डकी नदी गणेश हिमालबाट उत्पत्ति हुन्छ।\n- मर्स्याङ्दी नदी दामोदर हिमालबाट उत्पत्ति हुन्छ।\n- बुढी गंगा नदी जगदुल्ला तालबाट उत्पत्ति हुन्छ।', 'nepali'),
      (v_set_id, 9, E'ठूलोभेरी नदिको उद्गम देहायका मध्ये कुन हिमालबाट हुने गर्दछ ?', E'अपि हिमाल', E'धौलागिरी हिमाल', E'सैपाल हिमाल', E'मुकुट हिमाल', 'D', E'ठूलोभेरी नदीको उद्गम **मुकुट हिमालबाट** हुने गर्दछ।\n- सानो भेरी नदीको उद्गम धौलागिरी हिमालबाट हुन्छ।', 'nepali'),
      (v_set_id, 10, E'नदिनालाको सन्दर्भमा मुख भन्नाले के बुझिन्छ?', E'नदी उत्पादित हुने स्थान', E'नदी अन्त्य हुने स्थान', E'मिल्ने स-साना नदी', E'दुई नदी मिल्ने स्थान', 'B', E'नदिनालाको सन्दर्भमा मुख भन्नाले **नदी अन्त्य हुने स्थान** (जहाँ नदी समुद्र, ताल वा अर्को नदीमा गएर मिल्छ) लाई बुझिन्छ।\n- नदी उत्पादित हुने स्थानलाई मुहान (Source) भनिन्छ।\n- मुख्य नदीमा मिल्ने स-साना नदीलाई सहायक नदी (Tributary) भनिन्छ।\n- दुई नदी मिल्ने स्थानलाई संगम वा दोभान (Confluence) भनिन्छ।', 'nepali'),
      (v_set_id, 11, E'नेपालका नदिहरुको भारतको नाममा देहाएका मध्ये कुन विकल्प गलत छ ?', E'महाकाली - महानन्दा', E'बबई - सरयु', E'कर्णाली - घाँघरा', E'कन्काई - बेरिङ', 'A', E'नेपालका नदीहरूको भारतमा भएको नामको सन्दर्भमा **महाकाली - महानन्दा** को जोडा गलत छ। महाकाली नदीलाई भारतमा शारदा भनिन्छ।\n- बबई नदीलाई भारतमा सरयु भनिन्छ।\n- कर्णाली नदीलाई भारतमा घाँघरा भनिन्छ।\n- कन्काई नदीलाई भारतमा बेरिङ भनिन्छ।\nनोट: मेची नदीलाई भारतमा महानन्दा भनिन्छ।', 'nepali'),
      (v_set_id, 12, E'गणेश हिमालबाट उत्पत्ति भएको नदी देहायका मध्ये कुन हो?', E'सेती गण्डकी', E'मर्स्याङ्दी', E'बुढी गण्डकी', E'कालिगण्डकी', 'C', E'**बुढी गण्डकी नदीको उत्पत्ति गणेश हिमालबाट भएको हो।**\n- सेती गण्डकी, मादी र मोदी नदीको उत्पत्ति अन्नपूर्ण हिमालबाट हुन्छ।\n- मर्स्याङ्दी नदीको उत्पत्ति दामोदर हिमालबाट भएको हो।\n- कालिगण्डकी नदी मुस्ताङ लेकबाट उत्पत्ति हुन्छ।', 'nepali'),
      (v_set_id, 13, E'ठूलो भेरी र नसिङ्गाड नदीको दोभान जाजरकोटको कुन ठाउँमा रहेको छ?', E'रिम्ना', E'दल्ली', E'मटेला', E'खलंगा', 'B', E'ठूलो भेरी र नसिङ्गाड नदीको दोभान जाजरकोटको **दल्लीमा** रहेको छ।\n- रिम्नामा सानो भेरी र ठूलो भेरी नदीको दोभान पर्दछ।\n- मटेला जाजरकोट जिल्लामै पर्ने एक ठाउँ हो।\n- खलंगा जाजरकोट जिल्लाको सदरमुकाम हो।', 'nepali'),
      (v_set_id, 14, E'कोशी नदीको सिञ्चित क्षेत्र कति रहेको छ?', E'३३,००० वर्ग कि.मि.', E'२६,००० वर्ग कि.मि.', E'४९,००० वर्ग कि.मि.', E'३६,००० वर्ग कि.मि.', 'A', E'**कोशी नदीले करिब ३३,००० वर्ग कि.मी. क्षेत्र सिञ्चित गरेको छ।**\n- गण्डकी नदीले करिब २६,००० वर्ग कि.मी. क्षेत्र सिञ्चित गरेको छ।\n- कर्णाली नदीले करिब ४९,००० वर्ग कि.मी. क्षेत्र सिञ्चित गरेको छ।', 'nepali'),
      (v_set_id, 15, E'कोशी नदीका सातवटा सहायक नदीहरू मध्ये सबैभन्दा पश्चिमको सहायक नदी कुन हो?', E'इन्द्रावती', E'तमोर', E'अरुण', E'तामाकोशी', 'A', E'कोशी नदीका सहायक नदीहरूमध्ये सबैभन्दा पश्चिमको सहायक नदी **इन्द्रावती** हो।\n- तमोर कोशीको सबैभन्दा पूर्वको सहायक नदी हो।\n- अरुण पूर्वबाट दोस्रो सहायक नदी हो।\n- तामाकोशी कोशीको सहायक नदीहरूमध्ये एक हो जुन लिखु र सुनकोशीको बीचमा पर्दछ।\nनोट: कोशीका सहायक नदीहरूको पूर्वदेखि पश्चिमको क्रम: तमोर, अरुण, दुधकोशी, लिखु, तामाकोशी, सुनकोशी, र इन्द्रावती हो।', 'nepali'),
      (v_set_id, 16, E'प्रश्न वाचक चिन्ह भएको ठाँउमा उपयुक्त विकल्प छनोट गर्नुहोस् : (मेची:महानन्दा :: महाकाली:?)', E'बेरिङ', E'दामोदर', E'सरयु', E'शारदा', 'D', E'महाकाली नदीलाई भारतमा पुगेपछि **शारदा** नामले चिनिन्छ, जसरी मेची नदीलाई महानन्दा भनिन्छ।\n- कन्काई नदीलाई भारतमा बेरिङ भनिन्छ।\n- कोशी नदीलाई भारतमा दामोदर भनिन्छ।\n- बबई नदीलाई भारतमा सरयु भनिन्छ।', 'nepali'),
      (v_set_id, 17, E'कर्णाली नदीको नामाकरण कुन ऋषिको नामबाट भएको छ?', E'कौशिक ऋषि', E'गण्डव ऋषि', E'कर्णाद ऋषि', E'पञ्चेश्वर ऋषि', 'C', E'**कर्णाली नदीको नामाकरण कर्णाद ऋषिको नामबाट भएको हो।**\n- कौशिक ऋषिको नामबाट कोशी नदीको नामाकरण भएको हो।\n- गण्डव ऋषिको नामबाट गण्डकी नदीको नामाकरण भएको हो।\n- पञ्चेश्वर महाकाली नदीसँग सम्बन्धित एक पवित्र स्थल हो, कुनै ऋषिको नाम होइन।', 'nepali'),
      (v_set_id, 18, E'कोशी नदीको प्रभावित क्षेत्र पश्चिममा कुन हिमालसम्म रहेको छ ?', E'व्यास हिमाल', E'कन्चनजंघा हिमाल', E'धौलागिरी हिमाल', E'लाङटाङ हिमाल', 'D', E'कोशी नदीको जलाधार क्षेत्र पश्चिममा **लाङटाङ हिमाल** सम्म फैलिएको छ।\n- कन्चनजंघा हिमालले कोशी नदीको जलाधार क्षेत्रको पूर्वी सिमाना निर्धारण गर्दछ।\n- धौलागिरी हिमाल गण्डकी नदीको जलाधार क्षेत्रमा पर्दछ।\n- व्यास हिमाल दार्चुला जिल्लामा पर्छ र यो महाकाली नदीको जलाधार क्षेत्रसँग सम्बन्धित छ।', 'nepali'),
      (v_set_id, 19, E'देहायका मध्ये भोटमा मुल भएको नदि कुन होइन ?', E'तामाकोशी', E'कालिगण्डकी', E'कर्णाली', E'त्रिशुली', 'B', E'देहायका नदीहरूमध्ये **कालिगण्डकी** नदीको मुहान भोट (तिब्बत) मा होइन। यसको मुहान मुस्ताङ जिल्लाको न्हुविन हिमाल ग्लेसियरमा पर्दछ।\nनोट: भोटमा मुहान भएका प्रमुख नदीहरूमा अरुण, तामाकोशी, सुनकोशी, तमोर, कर्णाली र त्रिशुली पर्दछन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — नदी', 19;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- ताल (5 questions)  →  subtopic slug: nepal-geography-lakes
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-lakes' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-lakes';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — ताल' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — ताल';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — ताल', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'बैदाम तालको उपनामले कुन ताललाई चिनिन्छ?', E'सुर्मासरोवर ताल', E'फेवाताल', E'पन्चासे ताल', E'विष्णुतीर्थ ताल', 'B', E'**फेवाताललाई** बैदाम तालको उपनामले चिनिन्छ।\n- सुर्मासरोवर ताललाई ''आँखा आकारको ताल'' उपनामले चिनिन्छ।\n- पन्चासे ताललाई ''सफेदमा पात रहने ताल'' भनेर चिनिन्छ।\n- विष्णुतीर्थ ताल रानी पोखरीको अर्को नाम हो।', 'nepali'),
      (v_set_id, 2, E'नेपालको भूगोलमा भोकारी दह कुन जिल्लामा पर्दछ?', E'सिराहा', E'सप्तरी', E'सर्लाही', E'धनुषा', 'B', E'**भोकारी दह सप्तरी जिल्लामा पर्दछ।**\n- सिराहा जिल्लामा पतर पोखरी रहेको छ।\n- सर्लाही जिल्लामा भरत ताल पर्दछ।\n- धनुषा जिल्लामा गढगासागर, रामसागर र रत्नसागर तालहरू छन्।\nनोट: सप्तरी जिल्लामा ठाकुरबाबा दह पनि अवस्थित छ।', 'nepali'),
      (v_set_id, 3, E'देहायका मध्ये कुन कुण्ड बझाङ जिल्लामा अवस्थित रहेको छ ?', E'पाप कुण्ड', E'नारद कुण्ड', E'निहारी कुण्ड', E'ज्ञान कुण्ड', 'C', E'**निहारी कुण्ड बझाङ जिल्लामा अवस्थित छ।**\n- पाप कुण्ड मुगु जिल्लामा रहेको छ।\n- नारद कुण्ड गोरखा जिल्लामा पर्दछ।\n- ज्ञान कुण्ड धनुषा जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 4, E'स्यूर्पु ताल नेपालको कुन जिल्लामा अवस्थित प्रसिद्ध ताल हो?', E'रुकुम पश्चिम', E'रुकुम पूर्व', E'कास्कि', E'सुर्खेत', 'A', E'स्यूर्पु ताल **रुकुम पश्चिम** जिल्लामा अवस्थित प्रसिद्ध ताल हो।\n- रुकुम पूर्व जिल्लामा सुनपोखरी ताल रहेको छ।\n- कास्की जिल्लामा फेवा ताल, बेगनास ताल र रूपा ताल जस्ता प्रसिद्ध तालहरू छन्।\n- सुर्खेत जिल्लामा बुलबुले ताल अवस्थित छ।', 'nepali'),
      (v_set_id, 5, E'देहायका मध्ये कुन दह धादिङ जिल्लामा अवस्थित रहेको छ पहिचान गर्नुहोस् ?', E'कछुवा दह', E'सुन दह', E'कालोसेतो दह', E'मुरली दह', 'C', E'**कालोसेतो दह धादिङ जिल्लामा अवस्थित छ।**\n- कछुवा दह सल्यान जिल्लामा पर्दछ।\n- सुन दह डोटी जिल्लामा पर्दछ।\n- मुरली दह सुर्खेत जिल्लामा पर्दछ।\nनोट: धादिङ जिल्लामा गंगाजमुना कुण्ड पनि पर्दछ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — ताल', 5;
END $$;

