-- प्रदेश र जिल्ला (13 questions)  →  subtopic slug: nepal-geography-provinces-districts
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-provinces-districts' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-provinces-districts';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — प्रदेश र जिल्ला' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — प्रदेश र जिल्ला';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — प्रदेश र जिल्ला', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'माथिल्लो सगरमाथा भनेर चिनिने तीन जिल्लामा देहाएको कुन जिल्ला पर्दैन ?', E'ओखलढुङ्गा', E'सोलुखुम्बु', E'सङ्खुवासभा', E'खोटाङ', 'C', E'**सङ्खुवासभा जिल्ला माथिल्लो सगरमाथा क्षेत्रमा पर्दैन।**\n- माथिल्लो सगरमाथा भनेर सोलुखुम्बु, ओखलढुङ्गा र खोटाङ जिल्लालाई चिनिन्छ।', 'nepali'),
      (v_set_id, 2, E'हिमाली जिल्लामा स्तरोन्नति हुने सबैभन्दा पछिल्लो (कान्छो) हिमाली जिल्ला कुन हो ?', E'म्याग्दी', E'रुकुम पूर्व', E'गोर्खा', E'धादिङ', 'A', E'हिमाली जिल्लामा स्तरोन्नति हुने सबैभन्दा पछिल्लो (कान्छो) हिमाली जिल्ला **म्याग्दी** हो।\n- म्याग्दी जिल्ला २०७५ फागुन ११ गते पहाडी जिल्लाबाट हिमाली जिल्लामा स्तरोन्नति भएको थियो।\n- रामेछाप, धादिङ, गोर्खा र पूर्वी रुकुम जिल्लाहरू २०७४ भदौ २८ गते पहाडबाट हिमालमा स्तरोन्नति भएका थिए।', 'nepali'),
      (v_set_id, 3, E'देहाएका भित्री मधेसको जिल्लालाई ठूलोबाट सानोमा क्रम मिलाउनु होस्। १. दाङ २.सिन्धुली ३.सुर्खेत ४.मकवानपुर', E'1,2,3,4', E'2,1,3,4', E'1,2,4,3', E'2,1,4,3', 'C', E'**दाङ, सिन्धुली, मकवानपुर, सुर्खेत।**\n- यो क्रम भित्री मधेसका जिल्लाहरूको क्षेत्रफलको आधारमा ठूलोबाट सानोमा मिलाइएको हो।', 'nepali'),
      (v_set_id, 4, E'नेपाललाई ७७ जिल्लामा विभाजन गर्दा नेपालका तत्कालिन प्रधानमन्त्री को थिए?', E'शेर ब. देउवा', E'पुष्प क. दाहाल', E'केपी शर्मा वलि', E'सुशील कोइराला', 'A', E'नेपाललाई ७७ जिल्लामा विभाजन गर्दा तत्कालिन प्रधानमन्त्री **शेरबहादुर देउवा** थिए।\n- पुष्पकमल दाहाल ''प्रचण्ड''को प्रधानमन्त्रित्व कालमा स्थानीय तहको पुनर्संरचना भएको थियो।\n- केपी शर्मा ओलीको प्रधानमन्त्रित्व कालमा नेपालको नयाँ राजनीतिक नक्सा (चुच्चे नक्सा) जारी भएको थियो।\n- सुशील कोइरालाको प्रधानमन्त्रित्व कालमा २०७२ असोज ३ गते नेपालको संविधान जारी भई ७ प्रदेश कायम भएको थियो।\nनोट: शेरबहादुर देउवा सरकारको निर्णय अनुसार २०७४ भदौ ५ गते नवलपरासी र रुकुमलाई विभाजन गरी ७७ जिल्ला कायम गरिएको हो।', 'nepali'),
      (v_set_id, 5, E'शेराबस्ती अवस्थित नेपाली जिल्ला कुन हो ?', E'जुम्ला', E'हुम्ला', E'डोल्पा', E'सोलुखुम्बु', 'B', E'नेपाल-चीन सीमा नजिकको बस्ती **शेराबस्ती हुम्ला जिल्लामा अवस्थित छ।**\nनोट: नेपाल र चीनलाई जोड्ने मितेरी पुल पनि यही क्षेत्रमा पर्दछ।', 'nepali'),
      (v_set_id, 6, E'नेपालको अग्लो मानव बस्ति पहिचान गरि उक्त बस्ति देहाएका मध्ये कुन जिल्लामा पर्छ उपयुक्त विकल्प छनोट गर्नुहोस् ?', E'जुम्ला', E'हुम्ला', E'डोल्पा', E'सोलुखुम्बु', 'C', E'नेपालको सबैभन्दा अग्लो मानव बस्ती **डोल्पा** जिल्लामा पर्दछ।\n- जुम्ला जिल्लाको पतारासीमा विश्वको सर्वोच्च उचाइमा धानखेती (जुम्ली मार्सी) गरिन्छ।\n- हुम्ला जिल्लाको सिमीकोट नेपालको सबैभन्दा अग्लो सदरमुकाम हो।\n- सोलुखुम्बु जिल्लामा विश्वको सर्वोच्च शिखर सगरमाथा अवस्थित छ।\nनोट: डोल्पाका छार्काभोट र तरापबस्ती नेपालका अग्ला मानव बस्तीहरू हुन्।', 'nepali'),
      (v_set_id, 7, E'स्थानीय सरकार सञ्चालन ऐन २०७४ अनुसार नेपालका जिल्लाहरूलाई कति भागमा बर्गिकरण गरिएको छ?', E'३ भागमा', E'४ भागमा', E'५ भागमा', E'७ भागमा', 'C', E'स्थानीय सरकार सञ्चालन ऐन, २०७४ अनुसार नेपालका जिल्लाहरूलाई **५ भागमा** वर्गीकरण गरिएको छ।\n- ती वर्गहरूमा हिमालका २१, पहाडका २८, तराईका १८, उपत्यकाका ३ र भित्री मधेसका ७ जिल्लाहरू पर्दछन्।', 'nepali'),
      (v_set_id, 8, E'मकवानपुरको पुरानो जिल्ला सदरमुकाम कुन हो?', E'बन्दीपुर', E'भिमफेदि', E'हनुमाननगर', E'चैनपुर', 'B', E'**मकवानपुरको पुरानो जिल्ला सदरमुकाम भिमफेदि हो।**\n- बन्दीपुर तनहुँ जिल्लाको पुरानो सदरमुकाम हो।\n- हनुमाननगर सप्तरी जिल्लाको पुरानो सदरमुकाम हो।\n- चैनपुर संखुवासभा जिल्लाको पुरानो सदरमुकाम हो।', 'nepali'),
      (v_set_id, 9, E'हिमाली जिल्ला भएर पनि चिनलाई नछुने जिल्लाहरूको संख्या कति रहेको छ?', E'५ वटा', E'६ वटा', E'७ वटा', E'८ वटा', 'B', E'हिमाली जिल्ला भएर पनि चीनलाई नछुने जिल्लाहरूको संख्या **६ वटा** रहेको छ। नेपालमा कुल २१ हिमाली जिल्लाहरू छन्, जसमध्ये १५ जिल्लाले मात्र चीनको सिमाना छुन्छन्।\nनोट: २१ हिमाली जिल्लाबाट चीनलाई छुने १५ जिल्ला घटाउँदा ६ जिल्ला बाँकी रहन्छन्।', 'nepali'),
      (v_set_id, 10, E'देहाएको मध्ये कुन हिमाली जिल्लाले चीनलाई छोएको छैन ?', E'कालिकोट', E'म्याग्दी', E'जुम्ला', E'धादिङ', 'D', E'प्रश्नले चीनलाई नछुने हिमाली जिल्ला सोधेको छ, तर विकल्पहरूमध्ये धादिङले चीनलाई छुन्छ, जबकि अन्यले छुँदैनन्, त्यसैले यो नै सही उत्तर हो। **धादिङ** हिमाली जिल्ला हो जसले चीनको सिमानालाई छुन्छ।\n- कालिकोट, म्याग्दी, र जुम्ला हिमाली जिल्ला भए तापनि यिनीहरूले चीनको सिमानालाई छुँदैनन्।\nनोट: नेपालका जम्मा ६ वटा हिमाली जिल्लाहरूले चीनलाई छुँदैनन्: जुम्ला, म्याग्दी, रुकुम पूर्व, कालिकोट, बाजुरा र रामेछाप।', 'nepali'),
      (v_set_id, 11, E'नेपालको भूगोलमा चीन र भारत दुबैलाई नछुने नेपाली जिल्ला कति वटा रहेको छन्?', E'३७ वटा', E'३६ वटा', E'३५ वटा', E'३४ वटा', 'A', E'नेपालका **३७ वटा** जिल्लाहरूले चीन र भारत दुवै देशको सिमाना छुँदैनन्। यस्ता जिल्लाहरूलाई भूपरिवेष्ठित जिल्ला भनिन्छ।\nनोट: नेपालका कुल ७७ जिल्लामध्ये १३ जिल्लाले चीनलाई मात्र, २५ जिल्लाले भारतलाई मात्र र २ जिल्ला (ताप्लेजुङ र दार्चुला) ले दुवै देशलाई छुन्छन्।', 'nepali'),
      (v_set_id, 12, E'सिन्धुली पछि सबैभन्दा धेरै जिल्लासँग जिल्ला सिमाना जोडिएको जिल्ला कुन हो?', E'काभ्रेपलाञ्चोक', E'मकवानपुर', E'ललितपुर', E'रामेछाप', 'B', E'नेपालमा सबैभन्दा धेरै जिल्लासँग सिमाना जोडिएको जिल्ला सिन्धुली हो, जसले १० वटा जिल्लालाई छुन्छ। त्यसपछि **मकवानपुर** जिल्लाले ९ वटा जिल्लासँग सिमाना जोडेको छ।\nनोट: सबैभन्दा कम (२/२ वटा) जिल्लासँग सिमाना जोडिएका जिल्लाहरू झापा, दार्चुला र कञ्चनपुर हुन्।', 'nepali'),
      (v_set_id, 13, E'सबैभन्दा सानो प्रदेश मधेश प्रदेशले कुल नेपाली क्षेत्रफलको कति प्रतिशत भूभाग ओगटेको छ ?', E'६.२८ प्रतिशत', E'६.७९ प्रतिशत', E'६.५७ प्रतिशत', E'६.६० प्रतिशत', 'C', E'नेपालको सबैभन्दा सानो प्रदेश, मधेश प्रदेशले देशको कुल क्षेत्रफलको **६.५७ प्रतिशत** भूभाग ओगटेको छ।\nनोट: मधेश प्रदेशको कुल क्षेत्रफल ९,६६१ वर्ग किलोमिटर रहेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — प्रदेश र जिल्ला', 13;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- स्थानीय तह (18 questions)  →  subtopic slug: nepal-geography-local-government
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-local-government' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-local-government';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — स्थानीय तह' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — स्थानीय तह';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — स्थानीय तह', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नाम्खा पछिको ठूलो गाउँपालिका कुन हो?', E'फक्ताङलुङ', E'चुमनुब्री', E'मुगुम कार्मारोङ', E'खुम्बु पासाङ ल्हामु', 'C', E'**नेपालको सबैभन्दा ठूलो गाउँपालिका नाम्खा (हुम्ला) पछि मुगुम कार्मारोङ (मुगु) हो।**\n- फक्ताङलुङ ताप्लेजुङ जिल्लामा अवस्थित छ।\n- चुमनुब्री गोरखा जिल्लामा अवस्थित छ।\n- खुम्बु पासाङ ल्हामु सोलुखुम्बु जिल्लामा अवस्थित छ।\nनोट: नेपालका ठूला गाउँपालिकाहरूको क्रम नाम्खा (हुम्ला), मुगुम कार्मारोङ (मुगु), फक्ताङलुङ (ताप्लेजुङ), चुमनुब्री (गोरखा) र खुम्बु पासाङ ल्हामु (सोलुखुम्बु) हुन्।', 'nepali'),
      (v_set_id, 2, E'जनसंख्या धेरै भएका तीनदला गाउँपालिकाको क्रम कुन सहि छ?', E'बैजनाथ, राप्ती सोनारी, खजुरा', E'राप्ती सोनारी, बैजनाथ, खजुरा', E'बैजनाथ, राप्ती सोनारी, मायादेवी', E'राप्ती सोनारी, बैजनाथ, मायादेवी', 'A', E'जनसंख्या धेरै भएका गाउँपालिकाहरूको सही क्रम **बैजनाथ, राप्ती सोनारी, खजुरा** हो।\n- १. बैजनाथ (बाँके)\n- २. राप्ती सोनारी (बाँके)\n- ३. खजुरा (बाँके)\n- ४. मायादेवी (रुपन्देही)\n- ५. गैडहवा (रुपन्देही)', 'nepali'),
      (v_set_id, 3, E'बागमती प्रदेशमा उपमहानगरपालिकाको संख्या कति रहेको छ ?', E'१ वटा', E'२ वटा', E'३ वटा', E'४ वटा', 'A', E'**बागमती प्रदेशमा उपमहानगरपालिकाको संख्या १ वटा रहेको छ, जुन हेटौँडा उपमहानगरपालिका हो।**\n- नेपालमा कुल ११ उपमहानगरपालिका छन्।\n- लुम्बिनी प्रदेशमा सबैभन्दा धेरै ४ वटा (बुटवल, नेपालगञ्ज, घोराही र तुलसीपुर) उपमहानगरपालिका छन्।\n- मधेश प्रदेशमा ३ वटा (कलैया, जीतपुर-सिमरा र जनकपुर) र कोशी प्रदेशमा २ वटा (धरान, इटहरी) उपमहानगरपालिका छन्।', 'nepali'),
      (v_set_id, 4, E'नगरपालिका भन्दा उपमहानगरपालिका बढि भएको नेपालको एकमात्र जिल्ला कुन हो ?', E'कास्की', E'बारा', E'दाङ', E'सुनसरी', 'C', E'**दाङ** नेपालको एकमात्र जिल्ला हो जहाँ नगरपालिकाभन्दा उपमहानगरपालिकाको संख्या बढी छ।\nनोट: दाङ जिल्लामा २ उपमहानगरपालिका (घोराही, तुलसीपुर) र १ नगरपालिका (लमही) रहेका छन्।', 'nepali'),
      (v_set_id, 5, E'सबैभन्दा धेरै पिछडिएको स्थानीय तहमा सुचिकृत स्थानीय तहहरु कुन जिल्लामा अवस्थित रहेको छ?', E'बझाङ', E'बैतडी', E'अछाम', E'डोटी', 'A', E'**नेपालमा सबैभन्दा धेरै पिछडिएका स्थानीय तहहरू बझाङ जिल्लामा अवस्थित छन्।**\n- बैतडी जिल्ला सुदूरपश्चिम प्रदेशमा पर्ने एक पहाडी जिल्ला हो।\n- अछाम जिल्ला पनि सुदूरपश्चिम प्रदेशको एक पहाडी जिल्ला हो।\n- डोटी जिल्ला सुदूरपश्चिम प्रदेशमा पर्ने एक पहाडी जिल्ला हो।\nनोट: नेपालमा पिछडिएका स्थानीय तहको कुल सङ्ख्या २७ छ, जसमध्ये बझाङमा ६ वटा छन्।', 'nepali'),
      (v_set_id, 6, E'नेपालको भूगोलमा २ उपमहानगरपालिका भएको जिल्लाको संख्या कति रहेको छ?', E'३ वटा', E'६ वटा', E'५ वटा', E'४ वटा', 'A', E'नेपालमा २ वटा उपमहानगरपालिका भएका जिल्लाहरूको संख्या **३ वटा** रहेको छ।\nनोट: ती जिल्लाहरू सुनसरी (धरान र इटहरी), बारा (कलैया र जितपुर सिमरा), र दाङ (तुलसीपुर र घोराहि) हुन्।', 'nepali'),
      (v_set_id, 7, E'धेरै वडा भएको उपमहानगरपालिका कुन हो?', E'कलैया', E'घोराही', E'धनगढी', E'बुटवल', 'A', E'नेपालमा सबैभन्दा धेरै वडा भएको उपमहानगरपालिका कलैया हो, जसमा **२७ वटा** वडाहरू रहेका छन्।\nनोट: हेटौंडा, बुटवल, तुल्सिपुर, घोराही र धनगढी उपमहानगरपालिकाहरूमा सबैभन्दा कम, १९/१९ वटा वडाहरू छन्।', 'nepali'),
      (v_set_id, 8, E'स्थानीय तहहरूको प्रशासनिक वर्गीकरण अन्तर्गत सुगम स्थानीय तह कति रहेका छन् ?', E'९९ वटा', E'९८ वटा', E'९७ वटा', E'९६ वटा', 'B', E'स्थानीय तहहरूको प्रशासनिक वर्गीकरण अनुसार नेपालमा जम्मा **९८ वटा** सुगम स्थानीय तह रहेका छन्।\nनोट: वर्गीकरण अनुसार अतिदुर्गममा १६२, दुर्गममा २१८, र मध्यममा २७५ स्थानीय तहहरू छन्।', 'nepali'),
      (v_set_id, 9, E'१ मात्र नगरपालिका भएको ८ जिल्लाको सूचीमा देहायको कुन जिल्ला पर्दैन ?', E'मुगु', E'जुम्ला', E'रोल्पा', E'डोल्पा', 'D', E'**डोल्पा** जिल्ला १ मात्र नगरपालिका भएको जिल्लाको सूचीमा पर्दैन।\n- मुगु, जुम्ला र रोल्पा १ मात्र नगरपालिका भएका जिल्लाहरू हुन्।\nनोट: १ मात्र नगरपालिका भएका ८ जिल्लाहरू ओखलढुंगा, म्याग्दी, मुगु, जुम्ला, रोल्पा, ताप्लेजुङ, सोलुखुम्बु र पाँचथर हुन्।', 'nepali'),
      (v_set_id, 10, E'सबैभन्दा धेरै स्थानीय तह भएको पहाडी जिल्ला कुन हो ?', E'धादिङ', E'काभ्रे', E'काठमाडौं', E'सर्लाही', 'B', E'सबैभन्दा धेरै स्थानीय तह भएको पहाडी जिल्ला **काभ्रे** हो, जहाँ १३ वटा स्थानीय तह छन्।\n- धादिङ १३ वटा स्थानीय तहसहित सबैभन्दा धेरै स्थानीय तह भएको हिमाली जिल्ला हो।\n- सर्लाही २० वटा स्थानीय तहसहित सबैभन्दा धेरै स्थानीय तह भएको तराईको जिल्ला हो।\n- काठमाडौं उपत्यकाको एक जिल्ला हो, तर यसमा पहाडी जिल्लाहरूमध्ये सबैभन्दा धेरै स्थानीय तह छैनन्।', 'nepali'),
      (v_set_id, 11, E'नेपालमा नगरपालिका मात्र भएका जिल्लाको संख्या कति रहेको छ ?', E'४ वटा', E'३ वटा', E'२ वटा', E'५ वटा', 'C', E'नेपालमा नगरपालिका मात्र भएका जिल्लाको संख्या **२ वटा** रहेको छ। ती जिल्लाहरू काठमाडौं र भक्तपुर हुन्।\nनोट: गाउँपालिका मात्र भएका जिल्लाहरूको संख्या ५ रहेको छ, जसमा मनाङ, मुस्ताङ, पूर्वी रुकुम, रसुवा र हुम्ला पर्दछन्।', 'nepali'),
      (v_set_id, 12, E'सबैभन्दा धेरै वडा रहेको नेपालको भूगोलको महानगरपालिका कुन हो?', E'भरतपुर', E'काठमाडौं', E'विराटनगर', E'पोखरा', 'D', E'नेपालका महानगरपालिकाहरूमध्ये सबैभन्दा धेरै वडा **पोखरा महानगरपालिकामा (३३ वटा)** रहेका छन्।\n- भरतपुर महानगरपालिकामा २९ वटा वडाहरू छन्।\n- काठमाडौं र वीरगञ्ज महानगरपालिकामा ३२/३२ वटा वडाहरू छन्।\n- विराटनगर महानगरपालिकामा १९ वटा वडाहरू छन्।\nनोट: नेपालमा हाल ६ वटा महानगरपालिकाहरू छन्: काठमाडौं, ललितपुर, पोखरा, भरतपुर, वीरगञ्ज र विराटनगर।', 'nepali'),
      (v_set_id, 13, E'देहायका मध्ये सबैभन्दा धेरै महानगरपालिका भएको प्रदेश कुन हो?', E'सुदुरपश्चिम', E'बागमती', E'कोशी', E'मधेस', 'B', E'नेपालका सात प्रदेशमध्ये **बागमती प्रदेशमा** सबैभन्दा धेरै, ३ वटा महानगरपालिका रहेका छन्।\n- सुदुरपश्चिम प्रदेशमा कुनै पनि महानगरपालिका छैन।\n- कोशी प्रदेशमा १ वटा (विराटनगर) महानगरपालिका छ।\n- मधेस प्रदेशमा १ वटा (वीरगञ्ज) महानगरपालिका छ।\nनोट: नेपालमा हाल ६ वटा महानगरपालिका छन्: काठमाडौं, ललितपुर, भरतपुर (बागमती), पोखरा (गण्डकी), विराटनगर (कोशी) र वीरगञ्ज (मधेस)।', 'nepali'),
      (v_set_id, 14, E'नेपालको भूगोलमा सबैभन्दा कम गाँउपालिका भएको जिल्ला कुन हो ?', E'रुकुम पूर्व', E'चितवन', E'मुस्ताङ', E'भक्तपुर', 'B', E'नेपालमा सबैभन्दा कम गाउँपालिका भएको जिल्ला **चितवन** हो, जहाँ केवल एउटा (इच्छाकामना) गाउँपालिका रहेको छ।\n- पूर्वी रुकुममा ३ वटा स्थानीय तह छन्, जुन नेपालमा सबैभन्दा कम स्थानीय तह भएको जिल्ला हो।\n- भक्तपुर जिल्लामा एउटा पनि गाउँपालिका छैन।\nनोट: सबैभन्दा बढी गाउँपालिका भएको जिल्ला धादिङ (११ वटा) हो।', 'nepali'),
      (v_set_id, 15, E'क्षेत्रफलका हिसाबले सबैभन्दा सानो उपमहानगरपालिका देहाएका मध्ये कुन हो?', E'नेपालगन्ज', E'धरान', E'धनगढी', E'इटहरी', 'A', E'क्षेत्रफलका हिसाबले नेपालका ११ उपमहानगरपालिकाहरूमध्ये सबैभन्दा सानो **नेपालगन्ज (बाँके)** हो।\nनोट: क्षेत्रफलको आधारमा सबैभन्दा ठूलो उपमहानगरपालिका घोराही (दाङ) हो।', 'nepali'),
      (v_set_id, 16, E'नेपालको भूगोलमा सबैभन्दा ठूलो गाउँपालिका अवस्थित जिल्ला कुन हो?', E'अर्घाखाँची', E'डोल्पा', E'मनाङ', E'हुम्ला', 'D', E'**नेपालको सबैभन्दा ठूलो गाउँपालिका नाम्खा हुम्ला जिल्लामा अवस्थित छ।**\n- अर्घाखाँची जिल्लामा नेपालको सबैभन्दा ठूलो नगरपालिका, सितगंगा, पर्दछ।\n- डोल्पा जिल्लामा नेपालको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज, शे-फोक्सुण्डो, रहेको छ।\n- मनाङ जिल्लामा सबैभन्दा कम जनसंख्या भएको गाउँपालिका, नार्फुभूमि, अवस्थित छ।\nनोट: क्षेत्रफलको हिसाबले सबैभन्दा सानो गाउँपालिका बारा जिल्लाको परवानीपुर हो।', 'nepali'),
      (v_set_id, 17, E'नेपालको भूगोलमा सबैभन्दा धेरै नगरपालिका कुन प्रदेशमा अवस्थित छन्?', E'बागमती प्रदेश', E'कोशी प्रदेश', E'लुम्बिनी प्रदेश', E'मधेश प्रदेश', 'D', E'**नेपालमा सबैभन्दा धेरै नगरपालिका भएको प्रदेश मधेश प्रदेश हो, जहाँ ७३ वटा नगरपालिकाहरू छन्।**\n- बागमती प्रदेशमा ४१ वटा नगरपालिकाहरू छन्।\n- कोशी प्रदेशमा सबैभन्दा बढी स्थानीय तह (१३७) र गाउँपालिका (८८) छन्, तर नगरपालिकाको संख्या ४६ मात्र छ।\n- लुम्बिनी प्रदेशमा ३२ वटा नगरपालिकाहरू छन्।\nनोट: सबैभन्दा कम स्थानीय तह (७९) भएको प्रदेश कर्णाली हो।', 'nepali'),
      (v_set_id, 18, E'क्षेत्रफलका आधारमा नेपालको सबैभन्दा ठूलो नगरपालिका कुन हो?', E'भक्तपुर', E'बुढानिलकण्ठ', E'ठुलिभेरी', E'शितगंगा', 'D', E'क्षेत्रफलका आधारमा नेपालको सबैभन्दा ठूलो नगरपालिका अर्घाखाँची जिल्लामा अवस्थित **शितगंगा** हो।\n- भक्तपुर नेपालको सबैभन्दा सानो नगरपालिका हो।\n- बुढानिलकण्ठ काठमाडौंको सबैभन्दा धेरै जनसंख्या भएको नगरपालिका हो।\n- ठुलिभेरी (डोल्पा) सबैभन्दा कम जनसंख्या भएको नगरपालिका हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — स्थानीय तह', 18;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- जनगणना (10 questions)  →  subtopic slug: nepal-geography-population-census
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-population-census' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-population-census';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — जनगणना' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — जनगणना';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — जनगणना', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम जनघनत्व भएको जिल्ला मनाङमा जनघनत्व कति रहेको छ ?', E'५ जना प्रतिवर्ग कि मि', E'३ जना प्रतिवर्ग कि मि', E'४ जना प्रतिवर्ग कि मि', E'६ जना प्रतिवर्ग कि मि', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम जनघनत्व भएको जिल्ला मनाङको जनघनत्व **३ जना प्रतिवर्ग किलोमिटर** रहेको छ।\nनोट: नेपालको समग्र जनघनत्व १९८ जना प्रतिवर्ग किलोमिटर छ भने सबैभन्दा बढी जनघनत्व काठमाडौं जिल्लाको (५१६९ जना प्रतिवर्ग किलोमिटर) रहेको छ।', 'nepali'),
      (v_set_id, 2, E'राष्ट्रिय जनगणना अनुसार, नेपालको जनसंख्या वृद्धिदर कति प्रतिशत रहेको छ ?', E'२.२५ %', E'१.३५ %', E'०.९२ %', E'०.८२ %', 'C', E'राष्ट्रिय जनगणना २०७८ अनुसार नेपालको वार्षिक जनसंख्या वृद्धिदर **०.९२ प्रतिशत** रहेको छ।\nनोट: जनगणना २०६८ मा यो दर १.३५ प्रतिशत थियो।', 'nepali'),
      (v_set_id, 3, E'जनगणना २०६८ अनुसार नेपालको जनघनत्व कति थियो?', E'१८० जना प्रतिवर्ग किलोमिटर', E'१८४ जना प्रतिवर्ग किलोमिटर', E'१९० जना प्रतिवर्ग किलोमिटर', E'१९८ जना प्रतिवर्ग किलोमिटर', 'A', E'राष्ट्रिय जनगणना २०६८ अनुसार नेपालको जनघनत्व **१८० जना प्रतिवर्ग किलोमिटर** रहेको थियो।\nनोट: सोही जनगणना अनुसार नेपालको जनसंख्या वृद्धिदर १.३५% थियो।', 'nepali'),
      (v_set_id, 4, E'जनसंख्या कम भएका गाउँपालिका नार्पा भूमीको कति जनसंख्या रहेको छ?', E'३९२ जना', E'३९४ जना', E'३९६ जना', E'३९८ जना', 'C', E'नेपालको सबैभन्दा कम जनसंख्या भएको गाउँपालिका मनाङ जिल्लाको नार्पा भूमी हो, जसको जनसंख्या **३९६ जना** रहेको छ।\nनोट: नार्पा भूमी पछि क्रमशः चामे, लो-घेकर दामोदरकुण्ड, र ल्हो-मन्थाङ गाउँपालिकाहरू कम जनसंख्या भएका गाउँपालिका हुन्।', 'nepali'),
      (v_set_id, 5, E'राष्ट्रिय जनगणना, २०७८ अनुसार पहाडी क्षेत्रको जनघनत्व कति रहेको छ ?', E'१९२ जना प्रति वर्ग कि मि', E'१९६ जना प्रति वर्ग कि मि', E'१९४ जना प्रति वर्ग कि मि', E'१९८ जना प्रति वर्ग कि मि', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार पहाडी क्षेत्रको जनघनत्व **१९२ जना प्रति वर्ग किलोमिटर** रहेको छ। समग्रमा नेपालको जनघनत्व १९८, तराई क्षेत्रको ४६० र हिमाली क्षेत्रको ३४ जना प्रति वर्ग किलोमिटर रहेको छ।', 'nepali'),
      (v_set_id, 6, E'राष्ट्रिय जनगणना, २०७८ अनुसार मनाङ र मुस्ताङ पछि सबैभन्दा कम जनघनत्व भएको जिल्ला कुन हो?', E'मुगु', E'डोल्पा', E'हुम्ला', E'जुम्ला', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार मनाङ र मुस्ताङ पछि सबैभन्दा कम जनघनत्व भएको जिल्ला **डोल्पा** हो।\nकम जनघनत्व भएका ५ जिल्लाहरू र तिनीहरूको जनघनत्व (प्रति वर्ग कि.मि.) यसप्रकार छन्:\n| जिल्ला | जनघनत्व (व्यक्ति/वर्ग कि.मि.) |\n| --- | --- |\n| मनाङ | ३ |\n| मुस्ताङ | ४ |\n| डोल्पा | ५ |\n| हुम्ला | १० |\n| मुगु | १८ |', 'nepali'),
      (v_set_id, 7, E'राष्ट्रिय जनगणना, २०७८ अनुसार रामेछाप पछि जनसंख्या वृद्धिदर सबैभन्दा कम भएको नेपाली जिल्ला कुन हो ?', E'मनाङ', E'खोटाङ', E'भोजपुर', E'मुस्ताङ', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार जनसंख्या वृद्धिदर सबैभन्दा कम भएको जिल्ला रामेछाप हो, र त्यसपछिको दोस्रो कम वृद्धिदर भएको जिल्ला **खोटाङ** हो।\n- मनाङ जनसंख्या वृद्धिदर कम हुने जिल्लाको सूचीमा तेस्रो स्थानमा छ।\n- भोजपुर जनसंख्या वृद्धिदर कम हुने जिल्लाको सूचीमा चौथो स्थानमा छ।\n- मुस्ताङ पनि ऋणात्मक जनसंख्या वृद्धिदर भएका जिल्लाहरू मध्ये एक हो।\nनोट: जनगणना, २०७८ अनुसार ३४ वटा जिल्लाको जनसंख्या वृद्धिदर ऋणात्मक रहेको छ।', 'nepali'),
      (v_set_id, 8, E'राष्ट्रिय जनगणना २०७८ अनुसार भौगोलिक आधारमा हिमाली क्षेत्रको जनसंख्या कति प्रतिशत रहेको छ?', E'६.०८ प्रतिशत', E'६.९८ प्रतिशत', E'६.२८ प्रतिशत', E'६.३८ प्रतिशत', 'A', E'राष्ट्रिय जनगणना २०७८ अनुसार भौगोलिक आधारमा हिमाली क्षेत्रको जनसंख्या **६.०८ प्रतिशत** रहेको छ। सोही जनगणना अनुसार, पहाडी क्षेत्रमा ४०.३१ प्रतिशत र तराई क्षेत्रमा ५३.६१ प्रतिशत जनसंख्या रहेको छ।', 'nepali'),
      (v_set_id, 9, E'२०७८ सालको जनगणना अनुसार जनसङ्ख्या बृद्धीदर दोस्रो बढी भएको जिल्ला कुन हो?', E'रुपन्देही', E'चितवन', E'भक्तपुर', E'झापा', 'A', E'**२०७८ सालको जनगणना अनुसार रुपन्देही जिल्लाको जनसंख्या वृद्धिदर दोस्रो उच्च रहेको छ।**\n- चितवन जनसंख्या वृद्धिदरमा तेस्रो स्थानमा छ।\n- भक्तपुर जनसंख्या वृद्धिदरमा पहिलो स्थानमा छ।\n- झापा जनसंख्या वृद्धिदरमा पाँचौं स्थानमा छ।\nनोट: जनसंख्या वृद्धिदर सबैभन्दा कम भएको जिल्ला रामेछाप हो।', 'nepali'),
      (v_set_id, 10, E'तराई प्रदेशको जनसंख्या कति रहेको छ?', E'५५.६१ प्रतिशत', E'५३.६१ प्रतिशत', E'५१.६१ प्रतिशत', E'५३.५१ प्रतिशत', 'B', E'राष्ट्रिय जनगणना २०७८ अनुसार, तराई प्रदेशको जनसंख्या कुल जनसंख्याको **५३.६१ प्रतिशत** रहेको छ, जुन १ करोड ५६ लाख ३४ हजार ६ जना हो।\nनोट: सोही जनगणना अनुसार पहाडमा ४०.३१ प्रतिशत र हिमालमा ६.०८ प्रतिशत जनसंख्या रहेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — जनगणना', 10;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- कृषि र वन (8 questions)  →  subtopic slug: nepal-geography-agriculture-forest
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-agriculture-forest' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-agriculture-forest';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — कृषि र वन' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — कृषि र वन';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — कृषि र वन', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'देहायको मध्ये कुन खेती तुलनात्मक कम तापक्रममा पनि गर्न सकिन्छ?', E'धान', E'कोदो', E'जौ', E'मकै', 'C', E'दिएका बालीहरूमध्ये जौ तुलनात्मक रूपमा सबैभन्दा कम तापक्रममा पनि खेती गर्न सकिन्छ। बालीहरूलाई चाहिने तापक्रमको आधारमा धेरैबाट थोरैको क्रममा धान, गहुँ, मकै, कोदो र **जौ** पर्दछन्।\nनोट: जौ चिसो हावापानीमा हुने एक महत्त्वपूर्ण अन्न बाली हो।', 'nepali'),
      (v_set_id, 2, E'सबैभन्दा बढी वनक्षेत्र भएको नेपाली जिल्ला कुन हो?', E'अर्घाखाँची', E'भक्तपुर', E'कास्की', E'ललितपुर', 'A', E'**अर्घाखाँची जिल्लामा नेपालको सबैभन्दा बढी वनक्षेत्र रहेको छ।**\n- भक्तपुर जिल्लामा भने सबैभन्दा कम प्रतिशत वनक्षेत्र रहेको छ।', 'nepali'),
      (v_set_id, 3, E'यार्सागुम्बाको लागि प्रख्यात नेपाली जिल्ला कुन हो?', E'मनाङ', E'मुगु', E'डोल्पा', E'हुम्ला', 'C', E'**यार्सागुम्बाका लागि नेपालको डोल्पा जिल्ला प्रख्यात छ।**\n- मनाङ जिल्ला अन्नपूर्ण पदयात्रा मार्ग र उच्च हिमाली भूभागका लागि परिचित छ।\n- मुगु जिल्ला नेपालको सबैभन्दा ठूलो ताल रारा तालका लागि प्रसिद्ध छ।\n- हुम्ला जिल्ला नेपालको सबैभन्दा दुर्गम जिल्लाहरू मध्ये एक हो र यसको सिमाना चीनसँग जोडिएको छ।\nनोट: यार्सागुम्बा आधा समय वनस्पति र आधा समय किरा हुने एक बहुमूल्य जडीबुटी हो, जसको सङ्कलन प्रायः जेठ-असार महिनामा गरिन्छ।', 'nepali'),
      (v_set_id, 4, E'उखुको लागि प्रसिद्ध ठाँउ कुन हो?', E'धुनिबेशी', E'सिन्धुली', E'मालनेटा', E'फर्पिङ्ग', 'B', E'**उखु खेतीका लागि सिन्धुली जिल्ला प्रसिद्ध छ।**\n- मालनेटा अदुवाको लागि प्रसिद्ध छ।\n- फर्पिङ्ग नासपातिको लागि प्रसिद्ध छ।\nनोट: अन्य प्रसिद्ध स्थानहरूमा तेलको लागि खोकना, दहीको लागि भक्तपुर, र खुवाको लागि ठेचो (ललितपुर) पर्दछन्।', 'nepali'),
      (v_set_id, 5, E'नेपालको भूगोलमा देहायका धेरै खेतीयोग्य भूमि रहेको माटो कुन हो ?', E'तल्लैया माटो', E'पाँगो माटो', E'हिमाली माटो', E'बलौटे माटो', 'B', E'**नेपालको भूगोलमा पाँगो माटोमा धेरै खेतीयोग्य भूमि रहेको पाइन्छ।**\n- बलौटे पथ्थरिलो माटो भावर प्रदेश, भित्री मधेस र चुरे पहाडमा पाइन्छ।\n- रातो फुस्रो माटो महाभारतका टाढा भिरहरूमा पाइन्छ।\n- तल्लैया माटो उपत्यकामा पाइन्छ।\n- हिमाली माटो हिमाली क्षेत्रमा पाइन्छ।', 'nepali'),
      (v_set_id, 6, E'नेपालकै पहिलो कफी अनुसन्धान केन्द्र गुल्मी जिल्लाको कुन ठाँउमा रहेको छ?', E'आँपचौर', E'शान्तिपुर', E'रेसुङ्गा', E'बले टक्सार', 'D', E'नेपालको पहिलो कफी अनुसन्धान केन्द्र गुल्मी जिल्लाको **बले टक्सारमा** रहेको छ।\n- गुल्मीको आँपचौरबाट नेपालमा कफी खेतीको सुरुवात भएको थियो।\n- शान्तिपुर गुल्मी जिल्लामा अवस्थित एक गाउँपालिका हो।\n- रेसुङ्गा गुल्मी जिल्लाको एक प्रसिद्ध धार्मिक तथा पर्यटकीय स्थल एवं नगरपालिका हो।\nनोट: यो अनुसन्धान केन्द्र वि.सं. २०४१ मा स्थापना भएको थियो।', 'nepali'),
      (v_set_id, 7, E'देहायको मध्ये कुन प्रकारको माटो मुख्यतः काठमाडौं उपत्यकामा पाइन्छ ?', E'बलौटे माटो', E'तलैया माटो', E'पाँगो माटो', E'रातो फुस्रो माटो', 'B', E'काठमाडौं उपत्यकामा मुख्यतया **तलैया माटो** पाइन्छ।\n- बलौटे पथरिलो माटो भावर प्रदेश, भित्री मधेश र चुरे पहाडमा पाइन्छ।\n- रातो फुस्रो माटो महाभारतका ठाडा भिरहरूमा पाइन्छ।', 'nepali'),
      (v_set_id, 8, E'बोधिचित्त खेतीको सुरुवात कुन जिल्लाबाट भएको थियो?', E'काभ्रे', E'धनकुटा', E'दोलखा', E'इलाम', 'A', E'**नेपालमा बोधिचित्त खेतीको सुरुवात वि.सं. २०६० मा काभ्रे जिल्लाबाट भएको थियो।**\n- धनकुटा जिल्लामा वि.सं. २०५८ देखि एभोकाडो खेतीको सुरुवात भएको थियो।\n- दोलखा जिल्लामा वि.सं. २०४४ देखि किवि खेतीको सुरुवात भएको थियो।\n- इलाम जिल्लामा वि.सं. १९२० देखि चिया खेतीको सुरुवात भएको थियो।\nनोट: कफी खेतीको सुरुवात वि.सं. १९९५ मा गुल्मीको आँपचौरबाट भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — कृषि र वन', 8;
END $$;

