  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-hydropower-minerals';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — जलविद्युत र खनिज' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — जलविद्युत र खनिज';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — जलविद्युत र खनिज', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'चन्द्रढुङ्गाका लागि प्रसिद्ध नेपाली ठाउँ कुन हो?', E'बन्दीपुर, तनहुँ', E'फुलचोकी, काठमान्डौ', E'भैंसे दोभान, हेटौंडा', E'थाकखोला, मुस्ताङ', 'C', E'चन्द्रढुङ्गाका लागि प्रसिद्ध नेपाली ठाउँ **भैंसे दोभान, हेटौंडा** हो।\n- बन्दीपुर, तनहुँ सिसा (lead) को लागि प्रसिद्ध छ।\n- फुलचोकी, काठमान्डौ फलाम खानीको लागि परिचित छ।\n- थाकखोला, मुस्ताङ नुनखानीको लागि प्रसिद्ध छ।\nनोट: भैंसे दोभान तामा खानीका लागि पनि चिनिन्छ।', 'nepali'),
      (v_set_id, 2, E'कोसी बाँध (Koshi Barrage) मा जम्मा कतिवटा पानी नियन्त्रण गर्ने ढोका रहेका छन्?', E'५३ वटा', E'५४ वटा', E'५५ वटा', E'५६ वटा', 'D', E'कोसी बाँधमा जम्मा **५६ वटा** पानी नियन्त्रण गर्ने ढोका रहेका छन्। सन् १९५४ मा नेपाल र भारतबीच भएको सम्झौता अनुसार निर्माण भएको यो बाँध सन् १९६२ मा सम्पन्न भएको थियो।\nनोट: यो बाँधको कुल लम्बाइ ३७७० फिट छ र यसलाई भारतले १९९ वर्षका लागि लिजमा लिएको छ।', 'nepali'),
      (v_set_id, 3, E'चन्द्रनहर सिँचाइ आयोजना कुन जिल्लामा सञ्चालित रहेको छ?', E'नुवाकोट', E'कैलाली', E'कपिलवस्तु', E'सप्तरी', 'D', E'**चन्द्रनहर सिँचाइ आयोजना सप्तरी जिल्लामा सञ्चालित छ।**\n- कैलाली जिल्लामा मोहना सिँचाइ आयोजना रहेको छ।\n- कपिलवस्तु जिल्लामा बाणगंगा सिँचाइ आयोजना सञ्चालित छ।\n- नुवाकोट जिल्लामा बटटार सिँचाइ आयोजना रहेको छ।\nनोट: चन्द्रनहर नेपालको पहिलो नहर हो, जसको निर्माण वि.सं. १९६९ मा भएको थियो।', 'nepali'),
      (v_set_id, 4, E'निर्माण सम्पन्न मध्ये नेपालको सबैभन्दा ठूलो जलविद्युत आयोजना पहिचान गरि सो कुन जिल्लामा अवस्थित रहेको छ पत्ता लगाउनुहोस्?', E'लमजुङ', E'स्याङ्जा', E'दोलखा', E'सोलुखुम्बु', 'C', E'**नेपालको सबैभन्दा ठूलो जलविद्युत आयोजना माथिल्लो तामाकोशी जलविद्युत आयोजना हो, जुन दोलखा जिल्लामा अवस्थित छ।**\n- स्याङ्जा जिल्लामा कालीगण्डकी ''ए'' जलविद्युत आयोजना (१४४ मेगावाट) रहेको छ।\n- लमजुङ जिल्लामा मध्य-मर्स्याङ्दी जलविद्युत आयोजना (७० मेगावाट) र माथिल्लो मर्स्याङ्दी ''ए'' जलविद्युत आयोजना (५० मेगावाट) जस्ता आयोजनाहरू छन्।\n- सोलुखुम्बु जिल्लामा सोलु खोला (दूधकोशी) जलविद्युत आयोजना (८६ मेगावाट) लगायतका आयोजनाहरू छन्।\nनोट: माथिल्लो तामाकोशी जलविद्युत आयोजनाको क्षमता ४५६ मेगावाट हो।', 'nepali'),
      (v_set_id, 5, E'राजापुर सिंचाइ आयोजना कुन जिल्लामा सञ्चालित रहेको छ?', E'रुपन्देही', E'बर्दिया', E'बाँके', E'झापा', 'B', E'**राजापुर सिंचाइ आयोजना बर्दिया जिल्लामा सञ्चालित रहेको छ।**\n- रुपन्देही जिल्लामा तिनाउ सिंचाइ आयोजना सञ्चालित छ।\n- बाँके जिल्लामा सिक्टा सिंचाइ आयोजना सञ्चालित छ।\n- झापा जिल्लामा कन्काई सिंचाइ आयोजना सञ्चालित छ।', 'nepali'),
      (v_set_id, 6, E'सिक्‍टा सिंचाइ आयोजना कुन जिल्लामा सञ्चालित राष्ट्रिय गौरवको आयोजना हो?', E'रुपन्देही', E'बर्दिया', E'बाँके', E'झापा', 'C', E'**सिक्‍टा सिंचाइ आयोजना बाँके जिल्लामा सञ्चालित राष्ट्रिय गौरवको आयोजना हो।**\n- रुपन्देही जिल्लामा तिनाउ सिंचाइ आयोजना सञ्चालित छ।\n- बर्दिया जिल्लामा राजापुर सिंचाइ आयोजना रहेको छ।\n- झापा जिल्लामा कन्काई सिंचाइ आयोजना सञ्चालित छ।', 'nepali'),
      (v_set_id, 7, E'मर्स्याङ्दी जलविद्युत आयोजना कुन जिल्लामा सञ्चालित छ?', E'गुल्मी', E'लमजुङ', E'स्याङ्जा', E'तनहुँ', 'D', E'**मर्स्याङ्दी जलविद्युत आयोजना तनहुँ जिल्लामा सञ्चालित छ।**\n- लमजुङ जिल्लामा मध्य-मर्स्याङ्दी जलविद्युत आयोजना सञ्चालित छ।\n- स्याङ्जा जिल्लामा नेपालको कालीगण्डकी ''ए'' जलविद्युत आयोजना (१४४ मेगावाट) रहेको छ।\n- गुल्मी जिल्लामा रिडी खोला जलविद्युत आयोजना छ।\nनोट: मर्स्याङ्दी जलविद्युत आयोजनाको क्षमता ६९ मेगावाट हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — जलविद्युत र खनिज', 7;
END $$;

