-- पर्यटन र यातायात (19 questions)  →  subtopic slug: nepal-geography-tourism-transportation
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-tourism-transportation' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-tourism-transportation';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — पर्यटन र यातायात' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — पर्यटन र यातायात';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — पर्यटन र यातायात', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको नैनिताल भनेर कुन स्थानलाई चिनिन्छ?', E'त्रिवेणी धाम', E'लोमान्थाङ', E'जुम्ला', E'मनास्लु', 'A', E'**नवलपरासीको त्रिवेणी धामलाई नेपालको नैनिताल भनेर चिनिन्छ।**\n- लोमान्थाङ (मुस्ताङ) लाई नेपालको माटोको शहर भनिन्छ।\n- जुम्लालाई नेपालको दार्जिलिङ र नेपालको काश्मिर उपनामले चिनिन्छ।\n- मनास्लुलाई नेपालको माउन्ट फुजी भनिन्छ।', 'nepali'),
      (v_set_id, 2, E'टोड्के झरना कुन जिल्लामा रहेको छ पहिचान गर्नुहोस्?', E'डोल्पा', E'धादिङ', E'इलाम', E'ओखलढुंगा', 'C', E'**टोड्के झरना इलाम जिल्लामा अवस्थित छ।**\n- डोल्पा जिल्लामा सुलिगाड झरना रहेको छ।\n- धादिङ जिल्लामा गंगा जमुना झरना छ।\n- ओखलढुंगा जिल्लामा रातमाटे झरना रहेको छ।', 'nepali'),
      (v_set_id, 3, E'देहायका मध्ये कुन विमानस्थल गोर्खा जिल्लामा अवस्थित प्रसिद्ध विमानस्थल हो?', E'रुम्जाटार', E'पालुङटार', E'चन्दननाथ', E'राँझा', 'B', E'**पालुङटार विमानस्थल गोर्खा जिल्लामा अवस्थित छ।**\n- रुम्जाटार विमानस्थल ओखलढुंगा जिल्लामा पर्दछ।\n- चन्दननाथ विमानस्थल जुम्ला जिल्लामा रहेको छ।\n- राँझा विमानस्थल बाँके जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 4, E'नेपालको पहिलो औपचारिक होम स्टे कुन हो?', E'चल्ले गाउँ', E'भादा गाउँ', E'सिरुबारी', E'नगरकोट', 'C', E'स्याङ्जाको सिरुबारी नेपालको पहिलो औपचारिक होम स्टे हो। नेपालमा औपचारिक रुपमा होम स्टेको सुरुवात **वि.सं. २०६७ भाद्र १** गतेबाट भएको थियो।', 'nepali'),
      (v_set_id, 5, E'सात पोखरीको शहर भनेर कुन शहरलाई चिनिन्छ?', E'काठमाण्डौ', E'रसुवा', E'पोखरा', E'बनेपा', 'A', E'**सात पोखरीको शहर भनेर काठमाण्डौलाई चिनिन्छ।**\n- रसुवालाई सात कुण्डको जिल्ला भनेर चिनिन्छ।\n- पोखरालाई सात तालको शहर भनेर चिनिन्छ।\n- बनेपा काभ्रेपलाञ्चोक जिल्लामा अवस्थित एक ऐतिहासिक र व्यापारिक शहर हो।', 'nepali'),
      (v_set_id, 6, E'हरित सहर भनी हेटौंडालाई चिनिन्छ भने सेलिक सहर भनी कुनलाई चिनिन्छ ?', E'देवचुली', E'वालिङ', E'मटिहानी', E'धनकुटा', 'D', E'**सेलिक सहर भनेर धनकुटालाई चिनिन्छ।**\n- देवचुलीलाई बालमैत्री स्थानीय शासन नगर भनेर चिनिन्छ।\n- वालिङलाई गुलाबी सहर भनेर चिनिन्छ।\n- मटिहानीलाई फ्रि वाईफाई नगर भनेर चिनिन्छ।\nनोट: प्रश्नमा उल्लेख भए अनुसार, हेटौंडालाई हरित सहर (Green City) को उपनामले चिनिन्छ।', 'nepali'),
      (v_set_id, 7, E'कुशापानी झरणा, खरिगरा झरणा नेपालको कुन जिल्लामा अवस्थित छन?', E'सुर्खेत', E'दैलेख', E'अछाम', E'बझाङ', 'B', E'**कुशापानी झरणा र खरिगरा झरणा दैलेख जिल्लामा अवस्थित छन्।**\n- सुर्खेत जिल्लामा गिद्धे र गल्छेना झरनाहरू पर्दछन्।\n- अछाम जिल्लामा वैद्यनाथ झरना रहेको छ।\n- बझाङ जिल्लामा छहरा झरना अवस्थित छ।\nनोट: दैलेख जिल्लामा लाकुरी झरणा र द्वारीखोलाको झरना जस्ता अन्य झरनाहरू पनि रहेका छन्।', 'nepali'),
      (v_set_id, 8, E'वन्यजन्तु संग्रहालय नेपालको भूगोलको कुन जिल्लामा अवस्थित रहेको छ ?', E'गोदावरी, ललितपुर', E'पोखरा, कास्की', E'हेटौंडा, मकवानपुर', E'दमक, झापा', 'C', E'**वन्यजन्तु संग्रहालय हेटौंडा, मकवानपुरमा अवस्थित छ।**\n- गोदावरी, ललितपुरमा मृग अध्ययन केन्द्र रहेको छ।\n- पोखरा, कास्कीको फेवातालमा माछा संग्रहालय रहेको छ।\n- दमक, झापामा सर्प संग्रहालय रहेको छ।', 'nepali'),
      (v_set_id, 9, E'सरकारले सातै प्रदेशमा नयाँ पर्यटकीय गन्तव्य अन्तर्गत कुन प्रदेशको पर्यटकीय गन्तव्य निग्लिहवा हो?', E'कर्णाली प्रदेश', E'लुम्बिनी प्रदेश', E'कोशी प्रदेश', E'गण्डकी प्रदेश', 'B', E'सरकारले घोषणा गरेको नयाँ पर्यटकीय गन्तव्य निग्लिहवा **लुम्बिनी प्रदेशको** कपिलवस्तुमा पर्दछ।\n- कर्णाली प्रदेशको नयाँ पर्यटकीय गन्तव्य मुगुको रारा हो।\n- कोशी प्रदेशको नयाँ पर्यटकीय गन्तव्य इलामको सन्दकपुर हो।\n- गण्डकी प्रदेशको नयाँ पर्यटकीय गन्तव्य कास्कीको पञ्चासे हो।', 'nepali'),
      (v_set_id, 10, E'नेपालको भुगोलमा देवीघाट कुन जिल्लामा अवस्थित धार्मिक स्थान हो ?', E'नुवाकोट', E'रुपन्देही', E'तनहुँ', E'उदयपुर', 'A', E'**देवीघाट नुवाकोट जिल्लामा अवस्थित धार्मिक स्थान हो।**\n- रुपन्देही जिल्लामा सैनामैना पर्दछ।\n- तनहुँ जिल्लामा देवघाट अवस्थित छ।\n- उदयपुर जिल्लामा मैनामैनी पर्दछ।\nनोट: देवघाट र देवीघाट फरक-फरक स्थान हुन्، देवघाट तनहुँमा र देवीघाट नुवाकोटमा पर्दछ।', 'nepali'),
      (v_set_id, 11, E'अमलेखगन्जको पुरानो नाम के हो?', E'पदमकण्ठगिरी', E'भैसालोटन', E'भिच्छाखोरी', E'फुलोच्चगिरी', 'C', E'अमलेखगन्जको पुरानो नाम **भिच्छाखोरी** हो।\n- पदमकण्ठगिरी स्वयम्भूको पुरानो नाम हो।\n- भैसालोटन बाल्मिकीनगरको पुरानो नाम हो।\n- फुलोच्चगिरी फुल्चोकीको पुरानो नाम हो।', 'nepali'),
      (v_set_id, 12, E'विचित्र गुफा कुन जिल्लामा अवस्थित प्रसिद्ध गुफा हो?', E'तनहुँ', E'अर्घाखाँची', E'कास्की', E'गुल्मी', 'D', E'विचित्र गुफा **गुल्मी** जिल्लामा अवस्थित छ।\n- तनहुँ जिल्लामा सिद्ध गुफा अवस्थित छ।\n- अर्घाखाँची जिल्लामा साततले गुफा अवस्थित छ।\n- कास्की जिल्लामा महेन्द्र गुफा अवस्थित छ।', 'nepali'),
      (v_set_id, 13, E'नेपालको दोस्रो पुरानो विश्वविद्यालय “नेपाल संस्कृत विश्वविद्यालय” कुन जिल्लामा अवस्थित छ?', E'काभ्रे', E'दाङ', E'कास्की', E'सुर्खेत', 'B', E'**नेपालको दोस्रो पुरानो विश्वविद्यालय, नेपाल संस्कृत विश्वविद्यालय, दाङ जिल्लामा अवस्थित छ।**\n- काभ्रे जिल्लामा काठमाडौं विश्वविद्यालय रहेको छ।\n- कास्की जिल्लामा पोखरा विश्वविद्यालय रहेको छ।\n- सुर्खेत जिल्लामा मध्यपश्चिमाञ्चल विश्वविद्यालय रहेको छ।\nनोट: नेपाल संस्कृत विश्वविद्यालयको स्थापना वि.सं. २०४३ मा भएको थियो भने नेपालको पहिलो विश्वविद्यालय, त्रिभुवन विश्वविद्यालय, वि.सं. २०१६ मा स्थापना भएको हो।', 'nepali'),
      (v_set_id, 14, E'नेपाल र चिन बिचको प्रमुख व्यापारिक नाका मध्येको एक तिब्बतको पुरानो नाका ताक्लाकोट कुन जिल्लामा पर्दछ?', E'गोर्खा', E'रसुवा', E'दोलखा', E'बझाङ', 'D', E'तिब्बतको पुरानो व्यापारिक नाका ताक्लाकोट **बझाङ जिल्लामा** पर्दछ।\n- गोर्खा जिल्लामा लार्के भञ्ज्याङ नाका रहेको छ।\n- रसुवा जिल्लामा रसुवागढी नाका चीनसँगको प्रमुख व्यापारिक नाकाको रुपमा सञ्चालित छ।\n- दोलखा जिल्लामा दिर्घाचा र लामाबगर नाका रहेका छन्।\nनोट: नेपाल र चीन बीच १३ वटा व्यापारिक नाका रहेका छन्।', 'nepali'),
      (v_set_id, 15, E'दाङ-सल्यान-रुकुम सडक खण्डलाई के नामले चिनिन्छ ?', E'अरनिको राजमार्ग', E'रत्न राजमार्ग', E'कर्णाली राजमार्ग', E'राप्ती राजमार्ग', 'D', E'दाङ-सल्यान-रुकुम सडक खण्डलाई **राप्ती राजमार्ग** नामले चिनिन्छ, जुन दाङको अमेलियादेखि रुकुमको मुसिकोटसम्म फैलिएको छ।\n- अरनिको राजमार्ग काठमाडौंको माइतीघरदेखि कोदारीको मितेरी पुलसम्म पुग्छ।\n- रत्न राजमार्ग नेपालगन्जको जमुनिया सीमादेखि सुर्खेतको बाङ्गेसिमलसम्म फैलिएको छ।\n- कर्णाली राजमार्ग सुर्खेतको बाङ्गेसिमलदेखि जुम्ला र कालीकोटसम्म पुग्छ।', 'nepali'),
      (v_set_id, 16, E'सगरमाथा दिवस कहिले मनाइन्छ?', E'मे ९', E'मे ११', E'मे २९', E'मे ३०', 'C', E'सगरमाथा दिवस हरेक वर्ष **मे २९** मा मनाइन्छ। पहिलो पटक सगरमाथा आरोहण गर्ने तेन्जिङ नोर्गे शेर्पा र एडमण्ड हिलारीले सन् १९५३ मे २९ मा सफल आरोहण गरेका थिए, सोही दिनको सम्झनामा यो दिवस मनाउन थालिएको हो।\nनोट: नेपालमा सन् २००८ देखि औपचारिक रूपमा सगरमाथा दिवस मनाउन सुरु गरिएको हो।', 'nepali'),
      (v_set_id, 17, E'नेपालको भूगोलको सबैभन्दा अग्लो स्थानमा रहेको झरना कुन हो?', E'हयातुङ', E'अरुण', E'पचाल', E'सुलिगढ', 'D', E'नेपालको भूगोलको सबैभन्दा अग्लो स्थानमा (highest altitude) रहेको झरना **सुलिगढ झरना** हो, जुन डोल्पा जिल्लामा पर्दछ।\n- हयातुङ झरना नेपालको दोस्रो अग्लो (tallest) झरना हो, जुन ३६५ मिटर अग्लो छ र तेह्रथुममा पर्दछ।\n- अरुण नेपालको सबैभन्दा अग्लो स्थानमा बग्ने नदी हो।\n- पचाल झरना नेपालको सबैभन्दा अग्लो (tallest) झरना हो, जुन ३८१ मिटर अग्लो छ र कालिकोटमा पर्दछ।', 'nepali'),
      (v_set_id, 18, E'देहायका मध्ये कुन झरना डोटी जिल्लामा अवस्थित रहेको छ ?', E'जोरपानी झरना', E'रुप्से झरना', E'वैकुण्ठे झरना', E'सुलिगढ झरना', 'A', E'**जोरपानी झरना डोटी जिल्लामा अवस्थित छ।**\n- रुप्से झरना म्याग्दी जिल्लामा पर्दछ।\n- वैकुण्ठे झरना पाल्पा जिल्लामा अवस्थित छ।\n- सुलिगढ झरना डोल्पा जिल्लामा रहेको छ।', 'nepali'),
      (v_set_id, 19, E'नेपालको सबैभन्दा उच्च स्थानमा रहेको गुम्बा कुन हो ?', E'चम्पादेवि', E'मुक्तिनाथ', E'पाथिभरा', E'स्याङ्बोचे', 'D', E'**नेपालको सबैभन्दा उच्च स्थानमा रहेको गुम्बा स्याङ्बोचे हो।**\n- चम्पादेवी काठमाडौं उपत्यकाको दक्षिणमा रहेको एक डाँडा र धार्मिक स्थल हो।\n- मुक्तिनाथ नेपालको सबैभन्दा अग्लो स्थानमा रहेको मन्दिर हो, जुन मुस्ताङ जिल्लामा पर्दछ।\n- पाथिभरा नेपालको सबैभन्दा अग्लो स्थानमा रहेको देवीस्थान हो, जुन ताप्लेजुङ जिल्लामा पर्दछ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — पर्यटन र यातायात', 19;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- जलवायु र संरक्षित क्षेत्र (10 questions)  →  subtopic slug: nepal-geography-climate-protected-areas
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id    uuid;
  v_subtopic_id uuid;
  v_set_id      uuid;
  v_existing_id uuid;
  v_next_step   int;
BEGIN
  SELECT st.id, st.topic_id INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st WHERE st.slug = 'nepal-geography-climate-protected-areas' LIMIT 1;

  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic % not found in DB', 'nepal-geography-climate-protected-areas';
  END IF;

  SELECT id INTO v_existing_id FROM public.question_sets
  WHERE title = E'आसमान सङ्ग्रह — जलवायु र संरक्षित क्षेत्र' AND topic_id = v_topic_id LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान सङ्ग्रह — जलवायु र संरक्षित क्षेत्र';
    RETURN;
  END IF;

  INSERT INTO public.question_sets
    (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES
    (v_topic_id, v_subtopic_id, E'आसमान सङ्ग्रह — जलवायु र संरक्षित क्षेत्र', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'तराई क्षेत्रको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज कुन हो?', E'बर्दिया', E'बाँके', E'चितवन', E'पर्सा', 'A', E'तराई क्षेत्रको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज **बर्दिया** हो।\n- बाँके राष्ट्रिय निकुञ्ज बाघ संरक्षणका लागि स्थापना गरिएको हो।\n- चितवन राष्ट्रिय निकुञ्जमा सबैभन्दा धेरै पर्यटक घुम्न आउँछन्।\n- पर्सा राष्ट्रिय निकुञ्ज गौरी गाईको लागि प्रख्यात छ।', 'nepali'),
      (v_set_id, 2, E'नेपालको हावापानीको आधारमा पालुवा पलाउने ऋतु भनेर कुन ऋतुलाई चिनिन्छ?', E'ग्रीष्म ऋतु', E'वसन्त ऋतु', E'हेमन्त ऋतु', E'वर्षा ऋतु', 'B', E'नेपालको हावापानीको आधारमा पालुवा पलाउने ऋतु भनेर **वसन्त ऋतु**लाई चिनिन्छ।\n- ग्रीष्म ऋतुमा अत्यन्त गर्मी हुन्छ।\n- हेमन्त ऋतुमा चिसोको अनुभव भई जाडो बढ्छ।\n- वर्षा ऋतुमा अत्याधिक वर्षा हुन्छ।', 'nepali'),
      (v_set_id, 3, E'नेपालको हावापानीको आधारमा जेठ र असारमा कुन ऋतु पर्दछ?', E'ग्रीष्म ऋतु', E'वसन्त ऋतु', E'हेमन्त ऋतु', E'वर्षा ऋतु', 'A', E'नेपालको हावापानीको आधारमा जेठ र असार महिनामा **ग्रीष्म ऋतु** पर्दछ।\n- चैत र वैशाखमा वसन्त ऋतु पर्दछ।\n- साउन र भदौमा वर्षा ऋतु पर्दछ।\n- मंसिर र पुसमा हेमन्त ऋतु पर्दछ।\nनोट: नेपालमा असोज र कात्तिकमा शरद ऋतु तथा माघ र फागुनमा शिशिर ऋतु गरी जम्मा ६ ऋतुहरू अनुभव गरिन्छ।', 'nepali'),
      (v_set_id, 4, E'वायुउर्जाको लागि सम्भाव्य उपयुक्त नेपाली जिल्ला कुन हो ?', E'मुस्ताङ', E'सिन्धुपाल्चोक', E'मुस्ताङ', E'दैलेख', 'A', E'नेपालमा वायुउर्जा उत्पादनको लागि सबैभन्दा सम्भाव्य र उपयुक्त जिल्ला **मुस्ताङ** हो, जहाँ निरन्तर तीव्र गतिमा हावा बहन्छ।\n- सिन्धुपाल्चोक जिल्ला भू-तापीय ऊर्जा (Geothermal Energy) को लागि सम्भाव्य मानिन्छ।\n- दैलेख जिल्ला पेट्रोलियम पदार्थको अन्वेषण र उत्खननका लागि चर्चामा रहेको छ।\nनोट: वायु उर्जाबाट बिजुली निकाल्ने विश्वको पहिलो मुलुक डेनमार्क हो।', 'nepali'),
      (v_set_id, 5, E'मनास्लु संरक्षण क्षेत्र नेपालको कुन कुन जिल्लामा अवस्थित रहेको छ?', E'गोरखा र मुस्ताङ', E'मनाङ र मुस्ताङ', E'गोरखा र मनाङ', E'रामेछाप र दोलखा', 'C', E'मनास्लु संरक्षण क्षेत्र **गोरखा र मनाङ** जिल्लामा अवस्थित छ।\n- मुस्ताङ जिल्लामा अन्नपूर्ण संरक्षण क्षेत्र पर्दछ।\n- रामेछाप र दोलखा जिल्लाहरूमा गौरीशङ्कर संरक्षण क्षेत्र फैलिएको छ।\nनोट: मनास्लु संरक्षण क्षेत्रको स्थापना वि.सं. २०५५ (सन् १९९८) मा भएको हो।', 'nepali'),
      (v_set_id, 6, E'रसुवा, नुवाकोट, सिन्धुपाल्चोक जिल्लामा फैलिएको राष्ट्रिय निकुञ्ज कुन हो?', E'लाङटाङ', E'शुक्लाफाँटा', E'शिवपुरी नागार्जुन', E'मकालु वरुण', 'A', E'**लाङटाङ राष्ट्रिय निकुञ्ज रसुवा, नुवाकोट र सिन्धुपाल्चोक जिल्लामा फैलिएको छ।**\n- शुक्लाफाँटा राष्ट्रिय निकुञ्ज कञ्चनपुर जिल्लामा अवस्थित छ।\n- शिवपुरी नागार्जुन राष्ट्रिय निकुञ्ज काठमाडौं, नुवाकोट, सिन्धुपाल्चोक र धादिङ जिल्लाहरूमा फैलिएको छ।\n- मकालु वरुण राष्ट्रिय निकुञ्ज संखुवासभा र सोलुखुम्बु जिल्लामा अवस्थित छ।\nनोट: लाङटाङ राष्ट्रिय निकुञ्ज वि.सं. २०३२ मा स्थापना भएको थियो र यसको क्षेत्रफल १७१० वर्ग कि.मि. छ।', 'nepali'),
      (v_set_id, 7, E'अपिनाम्पा संरक्षण क्षेत्र नेपालको कुन जिल्लामा पर्दछ?', E'धादिङ', E'दार्चुला', E'दोलखा', E'दैलेख', 'B', E'अपिनाम्पा संरक्षण क्षेत्र **दार्चुला जिल्लामा** अवस्थित छ।\nनोट: यो संरक्षण क्षेत्र वि.सं. २०६७ मा स्थापना भएको हो र यसको क्षेत्रफल १,९०३ वर्ग किलोमिटर छ।', 'nepali'),
      (v_set_id, 8, E'नेपालमा पोखरापछि सबैभन्दा बढी पानी पर्ने ठाउँ कुन हो ?', E'गोदावरी', E'संखुवासभा', E'नेपालगन्ज', E'मुस्ताङ', 'B', E'नेपालमा पोखराको लुम्लेपछि सबैभन्दा बढी पानी पर्ने ठाउँ **संखुवासभा** हो।\n- गोदावरी काठमाडौं उपत्यकामा सबैभन्दा बढी पानी पर्ने ठाउँ हो।\n- नेपालगन्ज नेपालमा सबैभन्दा धेरै गर्मी हुने ठाउँ हो।\n- मुस्ताङ नेपालमा सबैभन्दा कम पानी पर्ने ठाउँ हो।', 'nepali'),
      (v_set_id, 9, E'देहायका मध्ये कुन केन्द्र चितवन जिल्लामा रहेको छैन?', E'हात्ती प्रजनन केन्द्र', E'गिद्ध प्रजनन केन्द्र', E'चमेरा संरक्षण क्षेत्र', E'जैविक विविधता सूचना केन्द्र', 'C', E'**चमेरा संरक्षण क्षेत्र कपिलवस्तु जिल्लाको देवानगढियामा रहेको छ।**\n- हात्ती प्रजनन केन्द्र चितवनको मेघौलीमा अवस्थित छ।\n- गिद्ध प्रजनन केन्द्र चितवनको कसरामा रहेको छ।\n- जैविक विविधता सूचना केन्द्र चितवनको टिकौलीमा अवस्थित छ।', 'nepali'),
      (v_set_id, 10, E'अन्नपूर्ण संरक्षण क्षेत्रको क्षेत्रफल कति रहेको छ?', E'६७९२ वर्ग कि.मि.', E'७२६९ वर्ग कि.मि.', E'७६२९ वर्ग कि.मि.', E'७६९२ वर्ग कि.मि.', 'C', E'अन्नपूर्ण संरक्षण क्षेत्रको क्षेत्रफल **७६२९ वर्ग कि.मि.** रहेको छ।\nनोट: यो नेपालको पहिलो संरक्षण क्षेत्र हो, जुन वि.सं. २०४९ मा स्थापना भएको थियो र लमजुङ, मनाङ, मुस्ताङ, म्याग्दी तथा कास्की जिल्लामा फैलिएको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान सङ्ग्रह — जलवायु र संरक्षित क्षेत्र', 10;
END $$;

